-- FOR REVIEW — run only after approval, as the postgres role (SQL editor / migration).
begin;
set local lock_timeout = '5s';
set local client_min_messages = warning;
set local statement_timeout = '60s';

-- ===== 01_schema.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — schema (FOR REVIEW — NOT APPLIED ANYWHERE)
--
--  Adds new cc_* objects only. Does NOT alter, drop or write to any
--  existing table. products_master and dc_stock_levels are only read (inside
--  cc_list_products, cc_create_order and cc_sold_by).
--
--  Apply 01 + 02 + 03 together in ONE transaction (see apply_cc.sql), so a
--  failure leaves nothing behind and no table is ever visible without RLS.
--  Safe to re-run: every statement is "if not exists" / "or replace".
-- =====================================================================

-- Preflight: stop before creating anything if this is not the expected database.
do $$
begin
  if to_regprocedure('auth.uid()') is null then
    raise exception 'auth.uid() غير موجود — ده مش مشروع Supabase. وقف التطبيق.';
  end if;
  if to_regclass('public.products_master') is null then
    raise exception 'جدول products_master غير موجود. وقف التطبيق.';
  end if;
  if (select count(*) from information_schema.columns
       where table_schema = 'public' and table_name = 'products_master'
         and column_name in ('sku', 'name', 'barcode', 'price')) <> 4 then
    raise exception 'products_master ناقصه عمود من (sku, name, barcode, price). وقف التطبيق.';
  end if;
  -- Storage Unit from the DC sheet decides "sold by weight" (read only).
  if (select count(*) from information_schema.columns
       where table_schema = 'public' and table_name = 'dc_stock_levels'
         and column_name in ('sku', 'unit')) <> 2 then
    raise exception 'جدول dc_stock_levels (sku, unit) غير موجود — مصدر «وحدة التخزين». وقف التطبيق.';
  end if;
end $$;

create sequence if not exists public.cc_order_no_seq start 1001;

-- Staff accounts (CONFIRMED: ONE shared call-center account, no roles — it can
-- do everything: orders, cancel, delivery areas). A row links to a Supabase Auth
-- user; the password lives in Supabase Auth only. "active = false" locks it out.
create table if not exists public.cc_staff (
  user_id      uuid primary key references auth.users(id) on delete cascade,
  display_name text not null,
  active       boolean not null default true,
  created_at   timestamptz not null default now()
);

-- Delivery areas and fees (managed from the app).
create table if not exists public.cc_delivery_areas (
  id         uuid primary key default gen_random_uuid(),
  name       text not null unique check (length(btrim(name)) between 1 and 80),
  fee        numeric(10,2) not null check (fee >= 0),
  active     boolean not null default true,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id)
);

-- Customers: one row per main mobile number (normalized 01xxxxxxxxx).
-- phone2 is optional and intentionally NOT unique (see review note L6).
create table if not exists public.cc_customers (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (length(btrim(name)) between 1 and 120),
  phone      text not null unique check (phone ~ '^0[0-9]{8,10}$'),
  phone2     text check (phone2 is null or phone2 ~ '^0[0-9]{8,10}$'),
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id)
);
create index if not exists cc_customers_phone2_idx on public.cc_customers (phone2);

-- Address length limits (L5). cc_create_order checks the same limits first and
-- returns a clear Arabic message; these constraints are the last line of defence.
create table if not exists public.cc_addresses (
  id          uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.cc_customers(id),
  area_id     uuid not null references public.cc_delivery_areas(id),
  label        text not null,                    -- اسم العنوان: البيت، الشغل، …
  street       text not null,                    -- الشارع (and building number, written by the call center)
  housing_type text,                             -- نوع السكن (optional): building = عمارة, villa = فيلا, office = مكتب
  notes        text,                             -- معلومات إضافية: floor, flat, landmark, …
  created_at   timestamptz not null default now(),
  created_by   uuid references auth.users(id),
  updated_at   timestamptz,
  updated_by   uuid references auth.users(id),
  constraint cc_addresses_label_len    check (char_length(btrim(label)) between 1 and 40),
  constraint cc_addresses_street_len   check (char_length(btrim(street)) between 1 and 150),
  constraint cc_addresses_housing_type check (housing_type is null or housing_type in ('building', 'villa', 'office')),
  constraint cc_addresses_notes_len    check (notes is null or char_length(notes) <= 200)
);
create index if not exists cc_addresses_customer_idx on public.cc_addresses (customer_id);

-- Orders. Customer, address, fee and prices are copied in (snapshots), so a
-- later price change in the sheet or an address edit never alters an order.
create table if not exists public.cc_orders (
  id                uuid primary key default gen_random_uuid(),
  order_no          text not null unique default ('CC-' || nextval('public.cc_order_no_seq')),
  client_request_id uuid not null unique,          -- idempotency key: one draft = one order
  created_at        timestamptz not null default now(),
  created_by        uuid not null references auth.users(id),
  created_by_name   text not null,
  payment_method    text not null default 'cash' check (payment_method = 'cash'),
  status            text not null default 'new' check (status in ('new', 'cancelled')),

  customer_id       uuid not null references public.cc_customers(id),
  customer_name     text not null,
  customer_phone    text not null,                -- number used for this order
  customer_phone2   text,                         -- second number, if any

  address_id        uuid references public.cc_addresses(id),
  area_id           uuid not null references public.cc_delivery_areas(id),
  area_name         text not null,
  address_label     text not null,
  street            text not null,
  housing_type      text,
  address_notes     text,

  delivery_fee      numeric(10,2) not null check (delivery_fee >= 0),
  subtotal          numeric(12,2) not null check (subtotal >= 0),
  total             numeric(12,2) not null check (total >= 0),
  is_estimated      boolean not null,               -- true when any line is sold by weight
  note              text check (note is null or length(note) <= 300),

  cancelled_at      timestamptz,
  cancelled_by      uuid references auth.users(id),
  cancelled_by_name text,
  cancel_reason     text,
  constraint cc_orders_cancel_consistent check (
    (status = 'cancelled') = (cancelled_at is not null and cancel_reason is not null)
  )
);
create index if not exists cc_orders_created_idx  on public.cc_orders (created_at desc);
create index if not exists cc_orders_phone_idx    on public.cc_orders (customer_phone, created_at desc);
create index if not exists cc_orders_customer_idx on public.cc_orders (customer_id);

-- Order lines: exactly one of qty (by piece) or weight_grams (by weight).
create table if not exists public.cc_order_items (
  id           bigint generated always as identity primary key,
  order_id     uuid not null references public.cc_orders(id) on delete cascade,
  line_no      int  not null,
  sku          text not null,
  product_name text not null,
  unit_price   numeric(12,2) not null check (unit_price >= 0),   -- price per piece, or per kg when weighed
  qty          int  check (qty between 1 and 999),
  weight_grams int  check (weight_grams between 10 and 20000),
  line_total   numeric(12,2) not null check (line_total >= 0),
  note         text check (note is null or length(note) <= 120),
  constraint cc_order_items_one_measure check ((qty is null) <> (weight_grams is null)),
  unique (order_id, line_no)
);

-- Status history (new / cancelled), shown in order details.
create table if not exists public.cc_order_events (
  id       bigint generated always as identity primary key,
  order_id uuid not null references public.cc_orders(id) on delete cascade,
  status   text not null check (status in ('new', 'cancelled')),
  at       timestamptz not null default now(),
  by       uuid references auth.users(id),
  by_name  text,
  reason   text
);
create index if not exists cc_order_events_order_idx on public.cc_order_events (order_id, at);

-- ===== 02_functions.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — functions (FOR REVIEW — NOT APPLIED ANYWHERE)
--
--  All writes go through these functions. The app never sends prices:
--  cc_create_order reads every price from products_master and every
--  delivery fee from cc_delivery_areas inside the database.
--
--  Every function is SECURITY DEFINER with search_path = '' (L1): nothing is
--  looked up through the search path, so every table, type and function is
--  written with its schema (public.*, auth.*). Built-ins come from pg_catalog,
--  which Postgres always searches first.
--
--  Errors meant for the user carry an Arabic message, a SQLSTATE and, for
--  form fields, HINT = the field name (label, street, phone, ...) so the
--  app can show the message under the right input.
-- =====================================================================

-- True when the signed-in user is the active call-center account.
-- (Earlier drafts had roles and a role function; 03_security.sql drops it.)
create or replace function public.cc_is_staff()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (select 1 from public.cc_staff s where s.user_id = auth.uid() and s.active)
$$;

-- ---------------------------------------------------------------------
-- How a product is sold (CONFIRMED): from the DC sheet's Storage Unit
-- (dc_stock_levels.unit, read only, joined by sku).
--   'weight' : every row for the sku says كيلو → quantity in kg, decimals allowed.
--   'unit'   : anything else (Unit, علبة, لتر, كرتونة, …) or no row → whole numbers only.
-- Unknown or mixed values fall back to 'unit' (the safer choice).
-- ---------------------------------------------------------------------
create or replace function public.cc_sold_by(p_sku text)
returns text
language sql stable security definer
set search_path = ''
as $$
  select case when bool_and(btrim(s.unit) = 'كيلو') then 'weight' else 'unit' end
    from public.dc_stock_levels s
   where s.sku = p_sku
$$;

-- ---------------------------------------------------------------------
-- Product list for the call center (M3). Replaces the earlier cc_products view.
--   • Active staff only; anyone else gets an error.
--   • Returns code, name, barcode, price and sold_by ('weight' | 'unit') —
--     never cost or margin.
--   • Keyset pages ordered by sku: pass the last sku of the previous page.
--     At most 1,000 rows per call (Supabase's default API row limit).
--   • A sku that appears more than once in products_master is left out (M4),
--     so the app can never show or order a product with an ambiguous price.
-- ---------------------------------------------------------------------
-- The result columns changed (sold_by added), and "create or replace" cannot
-- change them, so the old version is dropped first. Grants are re-applied in 03.
drop function if exists public.cc_list_products(text, int);
create function public.cc_list_products(p_after_sku text default null, p_limit int default 1000)
returns table (sku text, name text, barcode text, price numeric, sold_by text)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;

  return query
    select p.sku, p.name, p.barcode, coalesce(p.price, 0)::numeric(12,2),
           coalesce(public.cc_sold_by(p.sku), 'unit')
      from public.products_master p
     where p.sku is not null
       and (p_after_sku is null or p.sku > p_after_sku)
       and not exists (select 1 from public.products_master d
                        where d.sku = p.sku and d.ctid <> p.ctid)
     order by p.sku
     limit least(greatest(coalesce(p_limit, 1000), 1), 1000);
end;
$$;

-- ---------------------------------------------------------------------
-- Create an order.
--   p_client_request_id : generated by the app once per draft; repeating
--                         the call (double click, retry, two requests at the
--                         same moment) returns the same order.
--   p_customer : {"id": uuid, "order_phone"?: text, "phone2"?: text}
--             or {"name": text, "phone": text, "phone2"?: text}
--               phone2 on an existing customer is saved only if the customer has none yet;
--               it is always copied onto the order.
--   p_address  : {"id": uuid}                                   ← saved address as is
--             or {"id": uuid, "label", "area_id", "street", "housing_type"?, "notes"?}
--                                                               ← saved address, edited (all fields sent)
--             or {"label", "area_id", "street", "housing_type"?, "notes"?}   ← new address
--   Order type is delivery and payment is cash only. There is no order source (removed).
--   p_items    : [{"sku": text, "qty": int, "note"?: text}            ← products sold by unit
--               | {"sku": text, "weight_grams": int, "note"?: text}, ...] ← products sold by weight
--               The database checks each line against cc_sold_by(sku).
--   Any "price" sent by the app is ignored.
-- ---------------------------------------------------------------------
-- The earlier draft had a p_source argument; remove that version if a test run created it.
drop function if exists public.cc_create_order(uuid, text, jsonb, jsonb, jsonb, text);
create or replace function public.cc_create_order(
  p_client_request_id uuid,
  p_customer          jsonb,
  p_address           jsonb,
  p_items             jsonb,
  p_note              text default null
)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid      uuid := auth.uid();
  v_staff    public.cc_staff;
  v_order    public.cc_orders;
  v_customer public.cc_customers;
  v_address  public.cc_addresses;
  v_area     public.cc_delivery_areas;
  v_phone    text;
  v_phone2   text;
  v_addr_set boolean;
  v_housing  text;
  v_item     jsonb;
  v_prod     record;
  v_qty      int;
  v_grams    int;
  v_sold_by  text;
  v_total    numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_est      boolean := false;
  v_lines    jsonb := '[]'::jsonb;
  v_line_no  int := 0;
begin
  select * into v_staff from public.cc_staff where user_id = v_uid and active;
  if not found then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;

  if p_client_request_id is null then
    raise exception 'client_request_id مطلوب' using errcode = '22023';
  end if;

  -- M2: serialize requests that carry the same draft id. A second request that
  -- arrives at the same moment waits here until the first one commits, then the
  -- check below finds the finished order and returns it — no second customer,
  -- address or order is created. The lock is released at transaction end.
  perform pg_advisory_xact_lock(hashtextextended('cc_create_order:' || p_client_request_id::text, 0));

  -- Idempotency: same draft submitted again → return the existing order.
  select * into v_order from public.cc_orders where client_request_id = p_client_request_id;
  if found then
    return v_order;
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' then
    raise exception 'السلة فارغة أو غير صحيحة' using errcode = '22023', hint = 'items';
  end if;
  if jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 100 then
    raise exception 'السلة فارغة أو غير صحيحة' using errcode = '22023', hint = 'items';
  end if;

  -- Second number (optional), same format as the main one.
  v_phone2 := nullif(btrim(p_customer->>'phone2'), '');
  if v_phone2 is not null and v_phone2 !~ '^0[0-9]{8,10}$' then
    raise exception 'الرقم الإضافي غير صحيح' using errcode = '22023', hint = 'phone2';
  end if;

  -- Customer: existing by id, or new.
  if p_customer ? 'id' then
    select * into v_customer from public.cc_customers where id = (p_customer->>'id')::uuid;
    if not found then
      raise exception 'العميل غير موجود' using errcode = 'P0002', hint = 'customer';
    end if;
    v_phone := coalesce(nullif(p_customer->>'order_phone', ''), v_customer.phone);
    if v_phone not in (v_customer.phone, coalesce(v_customer.phone2, '')) then
      raise exception 'رقم التواصل لا يخص هذا العميل' using errcode = '22023', hint = 'order_phone';
    end if;
    -- A second number typed for a customer who has none is saved on the customer.
    if v_phone2 is not null and v_customer.phone2 is null and v_phone2 <> v_customer.phone then
      update public.cc_customers set phone2 = v_phone2 where id = v_customer.id
      returning * into v_customer;
    end if;
  else
    if char_length(coalesce(btrim(p_customer->>'name'), '')) not between 1 and 120 then
      raise exception 'اسم العميل مطلوب وبحد أقصى 120 حرف' using errcode = '22023', hint = 'name';
    end if;
    if coalesce(p_customer->>'phone', '') !~ '^0[0-9]{8,10}$' then
      raise exception 'رقم الموبايل غير صحيح — مثال: 01012345678' using errcode = '22023', hint = 'phone';
    end if;
    begin
      insert into public.cc_customers (name, phone, phone2, created_by)
      values (btrim(p_customer->>'name'), p_customer->>'phone', v_phone2, v_uid)
      returning * into v_customer;
    exception when unique_violation then
      raise exception 'رقم الموبايل مسجل لعميل آخر — اختاره من نتائج البحث' using errcode = '23505', hint = 'phone';
    end;
    v_phone := v_customer.phone;
  end if;

  -- Address (L5 limits): saved as is, saved + edited, or new. The fields of a
  -- new or edited address are checked here, with HINT = the form field name.
  v_addr_set := not (p_address ? 'id') or (p_address ? 'street');
  if v_addr_set then
    if char_length(coalesce(btrim(p_address->>'label'), '')) not between 1 and 40 then
      raise exception 'اسم العنوان مطلوب وبحد أقصى 40 حرف' using errcode = '22023', hint = 'label';
    end if;
    if nullif(p_address->>'area_id', '') is null then
      raise exception 'اختر منطقة التوصيل' using errcode = '22023', hint = 'areaId';
    end if;
    if char_length(coalesce(btrim(p_address->>'street'), '')) not between 1 and 150 then
      raise exception 'الشارع مطلوب وبحد أقصى 150 حرف' using errcode = '22023', hint = 'street';
    end if;
    v_housing := nullif(btrim(p_address->>'housing_type'), '');
    if v_housing is not null and v_housing not in ('building', 'villa', 'office') then
      raise exception 'نوع السكن غير صحيح' using errcode = '22023', hint = 'housingType';
    end if;
    if char_length(coalesce(p_address->>'notes', '')) > 200 then
      raise exception 'المعلومات الإضافية بحد أقصى 200 حرف' using errcode = '22023', hint = 'notes';
    end if;
  end if;

  if p_address ? 'id' then
    select * into v_address from public.cc_addresses
     where id = (p_address->>'id')::uuid and customer_id = v_customer.id
       for update;
    if not found then
      raise exception 'العنوان غير موجود لهذا العميل' using errcode = 'P0002', hint = 'address';
    end if;
    if v_addr_set then
      update public.cc_addresses
         set label = btrim(p_address->>'label'), area_id = (p_address->>'area_id')::uuid,
             street = btrim(p_address->>'street'), housing_type = v_housing,
             notes = nullif(btrim(p_address->>'notes'), ''), updated_at = now(), updated_by = v_uid
       where id = v_address.id
      returning * into v_address;
    end if;
  else
    insert into public.cc_addresses (customer_id, label, area_id, street, housing_type, notes, created_by)
    values (v_customer.id, btrim(p_address->>'label'), (p_address->>'area_id')::uuid, btrim(p_address->>'street'),
            v_housing, nullif(btrim(p_address->>'notes'), ''), v_uid)
    returning * into v_address;
  end if;

  -- Delivery fee comes from the area table, never from the app.
  select * into v_area from public.cc_delivery_areas where id = v_address.area_id;
  if not found or not v_area.active then
    raise exception 'منطقة التوصيل غير متاحة — اختر عنواناً آخر' using errcode = '22023', hint = 'areaId';
  end if;

  -- Lines: price from products_master; weight lines = price-per-kg × grams / 1000.
  for v_item in select value from jsonb_array_elements(p_items) loop
    v_line_no := v_line_no + 1;

    -- M4: STRICT — exactly one row per sku, otherwise stop (never pick an arbitrary price).
    begin
      select p.sku, p.name, coalesce(p.price, 0)::numeric(12,2) as price
        into strict v_prod
        from public.products_master p
       where p.sku = v_item->>'sku';
    exception
      when no_data_found then
        raise exception 'صنف غير موجود: %', v_item->>'sku' using errcode = 'P0002', hint = 'items';
      when too_many_rows then
        raise exception 'كود الصنف % مكرر في شيت المنتجات — لازم يتصلح في الشيت الأول', v_item->>'sku'
          using errcode = 'P0003', hint = 'items';
    end;

    -- Quantity must be a whole number (checked before casting, so 1.5 gets a clear message).
    if v_item ? 'qty' and coalesce(v_item->>'qty', '') !~ '^[0-9]+$' then
      if v_item->>'qty' ~ '^[0-9]*[.][0-9]+$' then
        raise exception 'لا يمكن أن تحتوي الكمية على أرقام عشرية في المنتجات التي يتم بيعها بالوحدة. (السطر %)', v_line_no
          using errcode = '22023', hint = 'items';
      end if;
      raise exception 'الكمية غير صحيحة في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    if v_item ? 'weight_grams' and coalesce(v_item->>'weight_grams', '') !~ '^[0-9]+$' then
      raise exception 'الوزن غير صحيح في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    v_qty   := (v_item->>'qty')::int;
    v_grams := (v_item->>'weight_grams')::int;
    if (v_qty is null) = (v_grams is null) then
      raise exception 'السطر % لازم يكون بالكمية أو بالوزن', v_line_no using errcode = '22023', hint = 'items';
    end if;

    -- The line must match how the product is sold.
    v_sold_by := coalesce(public.cc_sold_by(v_prod.sku), 'unit');
    if v_sold_by = 'unit' and v_grams is not null then
      raise exception 'الصنف «%» بيتباع بالوحدة — اكتب الكمية بالعدد', v_prod.name using errcode = '22023', hint = 'items';
    end if;
    if v_sold_by = 'weight' and v_qty is not null then
      raise exception 'الصنف «%» بيتباع بالوزن — اكتب الوزن بالكيلو', v_prod.name using errcode = '22023', hint = 'items';
    end if;
    if v_qty is not null and v_qty not between 1 and 999 then
      raise exception 'الكمية غير صحيحة في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    if v_grams is not null and v_grams not between 10 and 20000 then
      raise exception 'الوزن غير صحيح في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;

    if v_grams is not null then
      v_total := round(v_prod.price * v_grams / 1000.0, 2);
      v_est := true;
    else
      v_total := round(v_prod.price * v_qty, 2);
    end if;
    v_subtotal := v_subtotal + v_total;

    v_lines := v_lines || jsonb_build_object(
      'line_no', v_line_no, 'sku', v_prod.sku, 'product_name', v_prod.name,
      'unit_price', v_prod.price, 'qty', v_qty, 'weight_grams', v_grams,
      'line_total', v_total, 'note', left(nullif(btrim(v_item->>'note'), ''), 120));
  end loop;

  insert into public.cc_orders (
    client_request_id, created_by, created_by_name,
    customer_id, customer_name, customer_phone, customer_phone2,
    address_id, address_label, area_id, area_name, street, housing_type, address_notes,
    delivery_fee, subtotal, total, is_estimated, note)
  values (
    p_client_request_id, v_uid, v_staff.display_name,
    v_customer.id, v_customer.name, v_phone, nullif(coalesce(v_phone2, v_customer.phone2), v_phone),
    v_address.id, v_address.label, v_area.id, v_area.name, v_address.street, v_address.housing_type, v_address.notes,
    v_area.fee, v_subtotal, v_subtotal + v_area.fee, v_est, left(nullif(btrim(p_note), ''), 300))
  returning * into v_order;

  insert into public.cc_order_items (order_id, line_no, sku, product_name, unit_price, qty, weight_grams, line_total, note)
  select v_order.id, l.line_no, l.sku, l.product_name, l.unit_price, l.qty, l.weight_grams, l.line_total, l.note
    from jsonb_to_recordset(v_lines) as l(
      line_no int, sku text, product_name text, unit_price numeric, qty int,
      weight_grams int, line_total numeric, note text);

  insert into public.cc_order_events (order_id, status, by, by_name)
  values (v_order.id, 'new', v_uid, v_staff.display_name);

  return v_order;
end;
$$;

-- ---------------------------------------------------------------------
-- Cancel an order (call-center account, reason required, only from 'new').
-- ---------------------------------------------------------------------
create or replace function public.cc_cancel_order(p_order_id uuid, p_reason text)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_staff public.cc_staff;
  v_order public.cc_orders;
begin
  select * into v_staff from public.cc_staff where user_id = auth.uid() and active;
  if not found then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  if p_reason is null or length(btrim(p_reason)) = 0 then
    raise exception 'سبب الإلغاء مطلوب' using errcode = '22023', hint = 'reason';
  end if;

  update public.cc_orders
     set status = 'cancelled', cancelled_at = now(), cancelled_by = v_staff.user_id,
         cancelled_by_name = v_staff.display_name, cancel_reason = left(btrim(p_reason), 200)
   where id = p_order_id and status = 'new'
  returning * into v_order;
  if not found then
    raise exception 'الطلب غير موجود أو ملغي بالفعل' using errcode = 'P0002';
  end if;

  insert into public.cc_order_events (order_id, status, by, by_name, reason)
  values (v_order.id, 'cancelled', v_staff.user_id, v_staff.display_name, v_order.cancel_reason);
  return v_order;
end;
$$;

-- ---------------------------------------------------------------------
-- Add or edit a delivery area (call-center account). p_id null = new area.
-- ---------------------------------------------------------------------
create or replace function public.cc_save_area(p_id uuid, p_name text, p_fee numeric, p_active boolean)
returns public.cc_delivery_areas
language plpgsql security definer
set search_path = ''
as $$
declare
  v_area public.cc_delivery_areas;
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 80 then
    raise exception 'اسم المنطقة مطلوب وبحد أقصى 80 حرف' using errcode = '22023', hint = 'name';
  end if;
  if p_fee is null or p_fee < 0 then
    raise exception 'الرسوم لازم تكون رقم صفر أو أكتر' using errcode = '22023', hint = 'fee';
  end if;

  begin
    if p_id is null then
      insert into public.cc_delivery_areas (name, fee, active, updated_by)
      values (btrim(p_name), round(p_fee, 2), coalesce(p_active, true), auth.uid())
      returning * into v_area;
    else
      update public.cc_delivery_areas
         set name = btrim(p_name), fee = round(p_fee, 2), active = coalesce(p_active, active),
             updated_at = now(), updated_by = auth.uid()
       where id = p_id
      returning * into v_area;
      if not found then
        raise exception 'المنطقة غير موجودة' using errcode = 'P0002';
      end if;
    end if;
  exception when unique_violation then
    raise exception 'فيه منطقة بنفس الاسم' using errcode = '23505', hint = 'name';
  end;
  return v_area;
end;
$$;

-- ===== 03_security.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — RLS + grants (FOR REVIEW — NOT APPLIED ANYWHERE)
--
--  • anon (no login)          : no access to anything cc_*.
--  • signed in, not staff     : no rows, no products, cannot create orders.
--  • the active account       : read areas, customers, addresses, orders;
--                               products only through cc_list_products().
--  • writes                   : ONLY through the security-definer functions
--                               (create order / cancel / save area). No direct
--                               insert, update or delete on any cc_* table.
--  Explicit grants are included because newer Supabase projects require them
--  for Data API access. Safe to re-run (drop policy if exists + create).
-- =====================================================================

alter table public.cc_staff          enable row level security;
alter table public.cc_delivery_areas enable row level security;
alter table public.cc_customers      enable row level security;
alter table public.cc_addresses      enable row level security;
alter table public.cc_orders         enable row level security;
alter table public.cc_order_items    enable row level security;
alter table public.cc_order_events   enable row level security;

-- Start from zero (Supabase's default privileges grant ALL on new tables to anon/authenticated).
revoke all on public.cc_staff, public.cc_delivery_areas, public.cc_customers, public.cc_addresses,
              public.cc_orders, public.cc_order_items, public.cc_order_events
  from anon, authenticated, public;
revoke all on sequence public.cc_order_no_seq from anon, authenticated, public;

-- Read-only grants for signed-in users; RLS below decides which rows.
grant select on public.cc_staff, public.cc_delivery_areas, public.cc_customers, public.cc_addresses,
                public.cc_orders, public.cc_order_items, public.cc_order_events
  to authenticated;

-- Each user sees only their own staff row (the app checks it after login).
drop policy if exists cc_staff_self on public.cc_staff;
create policy cc_staff_self on public.cc_staff
  for select to authenticated using (user_id = auth.uid());

-- The active call-center account can read everything else (CONFIRMED: one shared account).
drop policy if exists cc_areas_staff_read     on public.cc_delivery_areas;
drop policy if exists cc_customers_staff_read on public.cc_customers;
drop policy if exists cc_addresses_staff_read on public.cc_addresses;
drop policy if exists cc_orders_staff_read    on public.cc_orders;
drop policy if exists cc_items_staff_read     on public.cc_order_items;
drop policy if exists cc_events_staff_read    on public.cc_order_events;
create policy cc_areas_staff_read     on public.cc_delivery_areas for select to authenticated using ((select public.cc_is_staff()));
create policy cc_customers_staff_read on public.cc_customers      for select to authenticated using ((select public.cc_is_staff()));
create policy cc_addresses_staff_read on public.cc_addresses      for select to authenticated using ((select public.cc_is_staff()));
create policy cc_orders_staff_read    on public.cc_orders         for select to authenticated using ((select public.cc_is_staff()));
create policy cc_items_staff_read     on public.cc_order_items    for select to authenticated using ((select public.cc_is_staff()));
create policy cc_events_staff_read    on public.cc_order_events   for select to authenticated using ((select public.cc_is_staff()));

-- M3: the earlier draft exposed products through a view; products are now read
-- only through cc_list_products(). Remove the draft view if a test run created it.
drop view if exists public.cc_products;

-- Functions: Postgres (and Supabase's default privileges) grant EXECUTE to
-- PUBLIC / anon on new functions — remove that, then allow signed-in users only.
-- Each function still checks the caller is the active account itself.
drop function if exists public.cc_my_role();   -- earlier draft (roles), replaced by cc_is_staff()
revoke all on function public.cc_is_staff()                                             from public, anon;
-- cc_sold_by is internal (used by the functions below); nobody calls it directly.
revoke all on function public.cc_sold_by(text)                                          from public, anon, authenticated;
revoke all on function public.cc_list_products(text, int)                               from public, anon;
revoke all on function public.cc_create_order(uuid, jsonb, jsonb, jsonb, text)          from public, anon;
revoke all on function public.cc_cancel_order(uuid, text)                               from public, anon;
revoke all on function public.cc_save_area(uuid, text, numeric, boolean)                from public, anon;

grant execute on function public.cc_is_staff()                                          to authenticated;
grant execute on function public.cc_list_products(text, int)                            to authenticated;
grant execute on function public.cc_create_order(uuid, jsonb, jsonb, jsonb, text) to authenticated;
grant execute on function public.cc_cancel_order(uuid, text)                            to authenticated;
grant execute on function public.cc_save_area(uuid, text, numeric, boolean)             to authenticated;

-- ===== 04_agents.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — employee names on orders (FOR REVIEW)
--
--  CONFIRMED: one shared login; after signing in, the person picks their
--  name from a fixed list. The name is saved on each order and on cancel.
--
--  ADDITIVE ONLY: one new table (cc_agents), three new columns on cc_orders,
--  three new functions. Nothing is dropped or deleted, and no table outside
--  cc_* is touched. Safe to re-run.
--  The existing cc_create_order / cc_cancel_order stay as they are; the app
--  now calls cc_place_order / cc_cancel_order_as, which use them and then
--  record the employee.
-- =====================================================================

-- Employee names (managed from the app's settings screen).
create table if not exists public.cc_agents (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(btrim(name)) between 1 and 40),
  active     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  updated_by uuid references auth.users(id)
);
-- "عمر" and "عمر " or "OMAR" and "omar" are the same person.
create unique index if not exists cc_agents_name_uq on public.cc_agents (lower(btrim(name)));

-- Who took the order / who cancelled it (copied in, so a later rename never changes old orders).
alter table public.cc_orders add column if not exists agent_id   uuid references public.cc_agents(id);
alter table public.cc_orders add column if not exists agent_name text;
alter table public.cc_orders add column if not exists cancelled_by_agent text;
create index if not exists cc_orders_agent_idx on public.cc_orders (agent_id, created_at desc);

-- Locked like the other cc_* tables: RLS on, staff read only, writes through functions.
alter table public.cc_agents enable row level security;
revoke all on public.cc_agents from anon, authenticated, public;
grant select on public.cc_agents to authenticated;
do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'cc_agents' and policyname = 'cc_agents_staff_read') then
    create policy cc_agents_staff_read on public.cc_agents for select to authenticated using ((select public.cc_is_staff()));
  end if;
end $$;

-- ---------------------------------------------------------------------
-- Add or edit an employee name. p_id null = new name.
-- ---------------------------------------------------------------------
create or replace function public.cc_save_agent(p_id uuid, p_name text, p_active boolean)
returns public.cc_agents
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent public.cc_agents;
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 40 then
    raise exception 'اكتب الاسم (بحد أقصى 40 حرف)' using errcode = '22023', hint = 'name';
  end if;
  begin
    if p_id is null then
      insert into public.cc_agents (name, active, updated_by)
      values (btrim(p_name), coalesce(p_active, true), auth.uid())
      returning * into v_agent;
    else
      update public.cc_agents
         set name = btrim(p_name), active = coalesce(p_active, active), updated_at = now(), updated_by = auth.uid()
       where id = p_id
      returning * into v_agent;
      if not found then
        raise exception 'الاسم غير موجود' using errcode = 'P0002';
      end if;
    end if;
  exception when unique_violation then
    raise exception 'الاسم ده موجود بالفعل في القايمة' using errcode = '23505', hint = 'name';
  end;
  return v_agent;
end;
$$;

-- Active employee or a clear error (shared by the two functions below).
create or replace function public.cc_require_agent(p_agent_id uuid)
returns public.cc_agents
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_agent public.cc_agents;
begin
  select * into v_agent from public.cc_agents where id = p_agent_id and active;
  if not found then
    raise exception 'اختار اسمك من قايمة الموظفين الأول' using errcode = '22023', hint = 'agent';
  end if;
  return v_agent;
end;
$$;

-- ---------------------------------------------------------------------
-- Create an order as an employee: same rules as cc_create_order (prices,
-- fees, units, same-draft protection), plus the employee's name.
-- Sending the same draft again returns the same order and keeps the first name.
-- ---------------------------------------------------------------------
create or replace function public.cc_place_order(
  p_agent_id          uuid,
  p_client_request_id uuid,
  p_customer          jsonb,
  p_address           jsonb,
  p_items             jsonb,
  p_note              text default null
)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent public.cc_agents;
  v_order public.cc_orders;
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  v_agent := public.cc_require_agent(p_agent_id);
  v_order := public.cc_create_order(p_client_request_id, p_customer, p_address, p_items, p_note);
  if v_order.agent_id is null then
    update public.cc_orders set agent_id = v_agent.id, agent_name = v_agent.name
     where id = v_order.id
    returning * into v_order;
    update public.cc_order_events set by_name = v_agent.name
     where order_id = v_order.id and status = 'new';
  end if;
  return v_order;
end;
$$;

-- ---------------------------------------------------------------------
-- Cancel as an employee: same rules as cc_cancel_order, plus the name.
-- ---------------------------------------------------------------------
create or replace function public.cc_cancel_order_as(p_agent_id uuid, p_order_id uuid, p_reason text)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent public.cc_agents;
  v_order public.cc_orders;
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  v_agent := public.cc_require_agent(p_agent_id);
  v_order := public.cc_cancel_order(p_order_id, p_reason);
  update public.cc_orders set cancelled_by_agent = v_agent.name
   where id = v_order.id
  returning * into v_order;
  update public.cc_order_events set by_name = v_agent.name
   where order_id = v_order.id and status = 'cancelled';
  return v_order;
end;
$$;

revoke all on function public.cc_save_agent(uuid, text, boolean)                         from public, anon;
revoke all on function public.cc_require_agent(uuid)                                     from public, anon, authenticated;
revoke all on function public.cc_place_order(uuid, uuid, jsonb, jsonb, jsonb, text)      from public, anon;
revoke all on function public.cc_cancel_order_as(uuid, uuid, text)                       from public, anon;
grant execute on function public.cc_save_agent(uuid, text, boolean)                      to authenticated;
grant execute on function public.cc_place_order(uuid, uuid, jsonb, jsonb, jsonb, text)   to authenticated;
grant execute on function public.cc_cancel_order_as(uuid, uuid, text)                    to authenticated;

-- ===== 05_sale_unit.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — "sold by weight" from the products sheet (FOR REVIEW)
--
--  CONFIRMED: the call center takes "by weight or by unit" from the products
--  sheet column is_sold_by_weight (same setting as Foodics). Products not in
--  that list fall back to the storage unit (dc_stock_levels: كيلو = weight).
--
--  ADDITIVE / CALL-CENTER ONLY:
--    • new table cc_product_sale_unit (sku → sold_by_weight), filled by the
--      call-center edge function cc-sale-unit from the same public products
--      file the data-center sync reads (read only);
--    • new table cc_sync_status (last run of that sync, for throttling and
--      for showing when it last worked);
--    • cc_sold_by (a call-center function) now checks the new table first.
--  Nothing is dropped or deleted. dc-sync, products_master, dc_products and
--  dc_stock_levels are not changed. Safe to re-run.
-- =====================================================================

create table if not exists public.cc_product_sale_unit (
  sku            text primary key,
  sold_by_weight boolean not null,
  updated_at     timestamptz not null default now()
);

create table if not exists public.cc_sync_status (
  name        text primary key,          -- 'sale_unit'
  started_at  timestamptz,
  finished_at timestamptz,
  ok          boolean,
  rows_total  integer,
  rows_changed integer,
  message     text
);

-- Only the edge function (service role) writes these; the app never reads them directly.
alter table public.cc_product_sale_unit enable row level security;
alter table public.cc_sync_status       enable row level security;
revoke all on public.cc_product_sale_unit, public.cc_sync_status from anon, authenticated, public;

-- ---------------------------------------------------------------------
-- How a product is sold: the products sheet first (is_sold_by_weight),
-- then the storage unit (كيلو = weight), otherwise by unit.
-- Same signature as before, so cc_list_products / cc_create_order use it as is.
-- ---------------------------------------------------------------------
create or replace function public.cc_sold_by(p_sku text)
returns text
language sql stable security definer
set search_path = ''
as $$
  select coalesce(
    (select case when u.sold_by_weight then 'weight' else 'unit' end
       from public.cc_product_sale_unit u where u.sku = p_sku),
    (select case when bool_and(btrim(s.unit) = 'كيلو') then 'weight' else 'unit' end
       from public.dc_stock_levels s where s.sku = p_sku having count(*) > 0),
    'unit')
$$;
revoke all on function public.cc_sold_by(text) from public, anon, authenticated;

-- When the products sheet sync last worked (shown to the call center if it gets old).
create or replace function public.cc_sale_unit_status()
returns table (finished_at timestamptz, ok boolean, rows_total integer, message text)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  return query
    select s.finished_at, s.ok, s.rows_total, s.message
      from public.cc_sync_status s where s.name = 'sale_unit';
end;
$$;
revoke all on function public.cc_sale_unit_status() from public, anon;
grant execute on function public.cc_sale_unit_status() to authenticated;

-- ===== 06_signup_code.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — join with a registration code (FOR REVIEW)
--
--  CONFIRMED: a new device/person can create an account from the sign-in
--  screen; to see anything they type the registration code (set by someone
--  already signed in, from the settings screen). A correct code links the
--  account as the call-center account; after that the device stays signed in.
--
--  ADDITIVE / CALL-CENTER ONLY: two new tables and four new functions.
--  Nothing is dropped or deleted. Only cc_* tables are written.
--  The code is never stored as plain text (salted SHA-256).
--  Guessing is limited: 5 wrong tries per account per hour, and 30 wrong
--  tries in total per hour lock joining for everyone until the hour passes.
-- =====================================================================

create table if not exists public.cc_settings (
  key        text primary key,          -- 'signup_code'
  salt       text,
  value_hash text,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id)
);

create table if not exists public.cc_join_attempts (
  id      bigint generated always as identity primary key,
  user_id uuid references auth.users(id) on delete cascade,
  ok      boolean not null,
  at      timestamptz not null default now()
);
create index if not exists cc_join_attempts_at_idx on public.cc_join_attempts (at desc);

alter table public.cc_settings      enable row level security;
alter table public.cc_join_attempts enable row level security;
revoke all on public.cc_settings, public.cc_join_attempts from anon, authenticated, public;

-- Salted SHA-256 (built in; no extension needed).
create or replace function public.cc_code_hash(p_salt text, p_code text)
returns text
language sql immutable security definer
set search_path = ''
as $$
  select encode(pg_catalog.sha256(convert_to(p_salt || ':' || btrim(p_code), 'UTF8')), 'hex')
$$;
revoke all on function public.cc_code_hash(text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Set or change the registration code (the active call-center account only).
-- ---------------------------------------------------------------------
create or replace function public.cc_set_signup_code(p_code text)
returns timestamptz
language plpgsql security definer
set search_path = ''
as $$
declare
  v_salt text := md5(random()::text || clock_timestamp()::text);
  v_at   timestamptz := now();
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  if p_code is null or char_length(btrim(p_code)) < 8 or char_length(btrim(p_code)) > 40 then
    raise exception 'الكود لازم يكون من 8 لـ 40 حرف/رقم' using errcode = '22023', hint = 'code';
  end if;
  insert into public.cc_settings (key, salt, value_hash, updated_at, updated_by)
  values ('signup_code', v_salt, public.cc_code_hash(v_salt, p_code), v_at, auth.uid())
  on conflict (key) do update
     set salt = excluded.salt, value_hash = excluded.value_hash,
         updated_at = excluded.updated_at, updated_by = excluded.updated_by;
  return v_at;
end;
$$;

-- Is a code set, and since when (never the code itself).
create or replace function public.cc_signup_code_status()
returns table (is_set boolean, updated_at timestamptz)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  return query
    select (s.value_hash is not null), s.updated_at
      from public.cc_settings s where s.key = 'signup_code'
    union all
    select false, null::timestamptz
     where not exists (select 1 from public.cc_settings s where s.key = 'signup_code');
end;
$$;

-- ---------------------------------------------------------------------
-- A signed-in account that is not linked yet joins with the code.
-- Returns true when linked (or already linked), false for a wrong code.
-- (A wrong code returns false instead of raising, so the failed try is kept
--  and counts toward the limits.)
-- ---------------------------------------------------------------------
create or replace function public.cc_join_with_code(p_code text)
returns boolean
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid   uuid := auth.uid();
  v_set   public.cc_settings;
  v_staff public.cc_staff;
begin
  if v_uid is null then
    raise exception 'سجّل دخول الأول' using errcode = '42501';
  end if;

  select * into v_staff from public.cc_staff where user_id = v_uid;
  if found then
    if v_staff.active then return true; end if;
    raise exception 'الأكونت ده متوقف — كلّم المسؤول' using errcode = '42501';
  end if;

  if (select count(*) from public.cc_join_attempts where not ok and user_id = v_uid and at > now() - interval '1 hour') >= 5 then
    raise exception 'محاولات كتير غلط — جرّب تاني بعد ساعة' using errcode = '54000', hint = 'code';
  end if;
  if (select count(*) from public.cc_join_attempts where not ok and at > now() - interval '1 hour') >= 30 then
    raise exception 'التسجيل متوقف مؤقتًا بسبب محاولات كتير غلط — جرّب تاني بعد ساعة' using errcode = '54000', hint = 'code';
  end if;

  select * into v_set from public.cc_settings where key = 'signup_code';
  if not found or v_set.value_hash is null then
    raise exception 'لسه مفيش كود تسجيل — اطلبه من المسؤول' using errcode = '22023', hint = 'code';
  end if;

  if p_code is null or public.cc_code_hash(v_set.salt, p_code) <> v_set.value_hash then
    insert into public.cc_join_attempts (user_id, ok) values (v_uid, false);
    return false;
  end if;

  insert into public.cc_staff (user_id, display_name) values (v_uid, 'مركز الاتصال')
  on conflict (user_id) do nothing;
  insert into public.cc_join_attempts (user_id, ok) values (v_uid, true);
  return true;
end;
$$;

revoke all on function public.cc_set_signup_code(text)    from public, anon;
revoke all on function public.cc_signup_code_status()     from public, anon;
revoke all on function public.cc_join_with_code(text)     from public, anon;
grant execute on function public.cc_set_signup_code(text) to authenticated;
grant execute on function public.cc_signup_code_status()  to authenticated;
grant execute on function public.cc_join_with_code(text)  to authenticated;

-- ===== 07_categories.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — product categories like Foodics (FOR REVIEW)
--
--  CONFIRMED: the order screen shows category cards (like Foodics). Names
--  come from the Foodics categories export (التصنيفات.csv: name, reference);
--  each product's category comes from the products export
--  (المنتجات.csv: category_reference).
--
--  ADDITIVE / CALL-CENTER ONLY: two new tables and one new function.
--  Filled by the call-center edge function cc-sale-unit (reads the two Drive
--  files, read only). Nothing is dropped or deleted; products_master and the
--  dc_* tables are not changed. Safe to re-run.
-- =====================================================================

create table if not exists public.cc_categories (
  reference  text primary key,               -- Foodics "الرقم المرجعي", lower case (c01 …)
  name       text not null,
  sort_order integer not null default 0,     -- row order in the Foodics export
  active     boolean not null default true,  -- false when it disappears from the export
  updated_at timestamptz not null default now()
);

create table if not exists public.cc_product_categories (
  sku        text primary key,
  reference  text,                           -- null = no category in the sheet
  updated_at timestamptz not null default now()
);

-- Only the edge function (service role) writes these; the app reads them through cc_list_categories().
alter table public.cc_categories         enable row level security;
alter table public.cc_product_categories enable row level security;
revoke all on public.cc_categories, public.cc_product_categories from anon, authenticated, public;

-- ---------------------------------------------------------------------
-- Categories with the codes (sku) of their products, in one call.
-- Categories with no products are left out.
-- ---------------------------------------------------------------------
create or replace function public.cc_list_categories()
returns table (reference text, name text, sort_order integer, skus text[])
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  return query
    select c.reference, c.name, c.sort_order, array_agg(pc.sku order by pc.sku)
      from public.cc_categories c
      join public.cc_product_categories pc on pc.reference = c.reference
     where c.active
     group by c.reference, c.name, c.sort_order
     order by c.sort_order, c.name;
end;
$$;
revoke all on function public.cc_list_categories() from public, anon;
grant execute on function public.cc_list_categories() to authenticated;

-- ===== 08_roles.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — three roles (FOR REVIEW)
--
--  CONFIRMED:
--    admin       — everything, plus «المناطق والموظفين» (areas/fees, employee
--                  names), the registration code and every account's role.
--    call_center — creates, follows and cancels orders. No settings.
--    prep        — the person preparing orders at the branch: only the
--                  preparation screen (comes in the next step). Sees nothing
--                  else and cannot create orders.
--  A new account that joins with the registration code is call_center.
--  The first time this runs, the active accounts that exist now become admin.
--
--  CALL-CENTER ONLY. Nothing is dropped or deleted. Changes to existing objects:
--    • cc_staff gets a "role" column (default call_center);
--    • cc_is_staff() now means "active admin or call_center" (prep sees no data);
--    • cc_save_area / cc_save_agent / cc_set_signup_code / cc_signup_code_status
--      now need an admin (same bodies, admin check instead of staff check).
--  Safe to re-run.
-- =====================================================================

alter table public.cc_staff add column if not exists role text not null default 'call_center';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'cc_staff_role_check') then
    alter table public.cc_staff add constraint cc_staff_role_check check (role in ('admin', 'call_center', 'prep'));
  end if;
end $$;

-- First run only: the accounts in use today become admin (no admin yet → nothing else changes later).
update public.cc_staff set role = 'admin'
 where active and not exists (select 1 from public.cc_staff where role = 'admin');

-- ---------------------------------------------------------------------
-- Role of the signed-in account (null = not an active account).
-- ---------------------------------------------------------------------
create or replace function public.cc_my_role()
returns text
language sql stable security definer
set search_path = ''
as $$
  select s.role from public.cc_staff s where s.user_id = auth.uid() and s.active
$$;

create or replace function public.cc_is_admin()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(public.cc_my_role() = 'admin', false)
$$;

-- Reads customers/orders/areas (all existing policies use this): admin and call_center only.
create or replace function public.cc_is_staff()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(public.cc_my_role() in ('admin', 'call_center'), false)
$$;

-- ---------------------------------------------------------------------
-- Settings: admin only (same bodies as before).
-- ---------------------------------------------------------------------
create or replace function public.cc_save_area(p_id uuid, p_name text, p_fee numeric, p_active boolean)
returns public.cc_delivery_areas
language plpgsql security definer
set search_path = ''
as $$
declare
  v_area public.cc_delivery_areas;
begin
  if not public.cc_is_admin() then
    raise exception 'المناطق والرسوم للأدمن بس' using errcode = '42501';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 80 then
    raise exception 'اسم المنطقة مطلوب وبحد أقصى 80 حرف' using errcode = '22023', hint = 'name';
  end if;
  if p_fee is null or p_fee < 0 then
    raise exception 'الرسوم لازم تكون رقم صفر أو أكتر' using errcode = '22023', hint = 'fee';
  end if;

  begin
    if p_id is null then
      insert into public.cc_delivery_areas (name, fee, active, updated_by)
      values (btrim(p_name), round(p_fee, 2), coalesce(p_active, true), auth.uid())
      returning * into v_area;
    else
      update public.cc_delivery_areas
         set name = btrim(p_name), fee = round(p_fee, 2), active = coalesce(p_active, active),
             updated_at = now(), updated_by = auth.uid()
       where id = p_id
      returning * into v_area;
      if not found then
        raise exception 'المنطقة غير موجودة' using errcode = 'P0002';
      end if;
    end if;
  exception when unique_violation then
    raise exception 'فيه منطقة بنفس الاسم' using errcode = '23505', hint = 'name';
  end;
  return v_area;
end;
$$;

create or replace function public.cc_save_agent(p_id uuid, p_name text, p_active boolean)
returns public.cc_agents
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent public.cc_agents;
begin
  if not public.cc_is_admin() then
    raise exception 'أسماء الموظفين للأدمن بس' using errcode = '42501';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 40 then
    raise exception 'اكتب الاسم (بحد أقصى 40 حرف)' using errcode = '22023', hint = 'name';
  end if;
  begin
    if p_id is null then
      insert into public.cc_agents (name, active, updated_by)
      values (btrim(p_name), coalesce(p_active, true), auth.uid())
      returning * into v_agent;
    else
      update public.cc_agents
         set name = btrim(p_name), active = coalesce(p_active, active), updated_at = now(), updated_by = auth.uid()
       where id = p_id
      returning * into v_agent;
      if not found then
        raise exception 'الاسم غير موجود' using errcode = 'P0002';
      end if;
    end if;
  exception when unique_violation then
    raise exception 'الاسم ده موجود بالفعل في القايمة' using errcode = '23505', hint = 'name';
  end;
  return v_agent;
end;
$$;

create or replace function public.cc_set_signup_code(p_code text)
returns timestamptz
language plpgsql security definer
set search_path = ''
as $$
declare
  v_salt text := md5(random()::text || clock_timestamp()::text);
  v_at   timestamptz := now();
begin
  if not public.cc_is_admin() then
    raise exception 'كود التسجيل للأدمن بس' using errcode = '42501';
  end if;
  if p_code is null or char_length(btrim(p_code)) < 8 or char_length(btrim(p_code)) > 40 then
    raise exception 'الكود لازم يكون من 8 لـ 40 حرف/رقم' using errcode = '22023', hint = 'code';
  end if;
  insert into public.cc_settings (key, salt, value_hash, updated_at, updated_by)
  values ('signup_code', v_salt, public.cc_code_hash(v_salt, p_code), v_at, auth.uid())
  on conflict (key) do update
     set salt = excluded.salt, value_hash = excluded.value_hash,
         updated_at = excluded.updated_at, updated_by = excluded.updated_by;
  return v_at;
end;
$$;

create or replace function public.cc_signup_code_status()
returns table (is_set boolean, updated_at timestamptz)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_admin() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  return query
    select (s.value_hash is not null), s.updated_at
      from public.cc_settings s where s.key = 'signup_code'
    union all
    select false, null::timestamptz
     where not exists (select 1 from public.cc_settings s where s.key = 'signup_code');
end;
$$;

-- ---------------------------------------------------------------------
-- Accounts and roles (admin only).
-- ---------------------------------------------------------------------
create or replace function public.cc_list_staff()
returns table (user_id uuid, email text, role text, active boolean, created_at timestamptz)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_admin() then
    raise exception 'الحسابات للأدمن بس' using errcode = '42501';
  end if;
  return query
    select s.user_id, u.email::text, s.role, s.active, s.created_at
      from public.cc_staff s join auth.users u on u.id = s.user_id
     order by s.created_at;
end;
$$;

-- Change an account's role or stop/start it. An admin cannot change their own
-- account (so the last admin can never lock everyone out).
create or replace function public.cc_set_staff(p_user_id uuid, p_role text, p_active boolean)
returns boolean
language plpgsql security definer
set search_path = ''
as $$
begin
  if not public.cc_is_admin() then
    raise exception 'الحسابات للأدمن بس' using errcode = '42501';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'مش هتقدر تغيّر صلاحية أكونتك إنت' using errcode = '22023', hint = 'self';
  end if;
  if p_role is null or p_role not in ('admin', 'call_center', 'prep') then
    raise exception 'صلاحية غير معروفة' using errcode = '22023', hint = 'role';
  end if;
  update public.cc_staff set role = p_role, active = coalesce(p_active, active) where user_id = p_user_id;
  if not found then
    raise exception 'الأكونت غير موجود' using errcode = 'P0002';
  end if;
  return true;
end;
$$;

revoke all on function public.cc_my_role()    from public, anon;
revoke all on function public.cc_is_admin()   from public, anon;
revoke all on function public.cc_list_staff() from public, anon;
revoke all on function public.cc_set_staff(uuid, text, boolean) from public, anon;
grant execute on function public.cc_my_role()    to authenticated;
grant execute on function public.cc_is_admin()   to authenticated;
grant execute on function public.cc_list_staff() to authenticated;
grant execute on function public.cc_set_staff(uuid, text, boolean) to authenticated;

-- ===== 09_prep.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — preparation stages (FOR REVIEW)
--
--  CONFIRMED: the person preparing orders at the branch (role "prep") sees the
--  orders sent by the call center and moves each one on with one tap:
--      new → preparing (استلم وبدأ) → at_cashier (على الكاشير) → out (خرج مع الطيار)
--  One step back is allowed (a wrong tap). The call center sees the stage and
--  its times. The call center prints the ticket; the preparation screen does not.
--
--  CALL-CENTER ONLY, ADDITIVE: new columns on cc_orders (stage + its times,
--  existing orders start at "new"), one new log table, two new functions.
--  Nothing is dropped or deleted; existing checks and functions are unchanged.
--  Safe to re-run.
-- =====================================================================

alter table public.cc_orders add column if not exists stage         text not null default 'new';
alter table public.cc_orders add column if not exists preparing_at  timestamptz;
alter table public.cc_orders add column if not exists at_cashier_at timestamptz;
alter table public.cc_orders add column if not exists out_at        timestamptz;
alter table public.cc_orders add column if not exists stage_by_name text;     -- account that made the last change
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'cc_orders_stage_check') then
    alter table public.cc_orders add constraint cc_orders_stage_check
      check (stage in ('new', 'preparing', 'at_cashier', 'out'));
  end if;
end $$;
create index if not exists cc_orders_stage_idx on public.cc_orders (stage, created_at desc);

-- Every tap, for the record (who and when). Written only by cc_set_stage.
create table if not exists public.cc_order_stage_events (
  id        bigint generated always as identity primary key,
  order_id  uuid not null references public.cc_orders(id),
  stage     text not null check (stage in ('new', 'preparing', 'at_cashier', 'out')),
  at        timestamptz not null default now(),
  by_user   uuid references auth.users(id),
  by_name   text
);
create index if not exists cc_order_stage_events_order_idx on public.cc_order_stage_events (order_id, at);
alter table public.cc_order_stage_events enable row level security;
revoke all on public.cc_order_stage_events from anon, authenticated, public;

-- ---------------------------------------------------------------------
-- The preparation list: today's orders (Cairo time), plus any older order
-- that is still not out. Only what preparing needs — no prices.
-- ---------------------------------------------------------------------
create or replace function public.cc_prep_orders()
returns setof jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Africa/Cairo')) at time zone 'Africa/Cairo';
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'شاشة التجهيز للفرع بس' using errcode = '42501';
  end if;
  return query
    select jsonb_build_object(
      'id', o.id, 'order_no', o.order_no, 'created_at', o.created_at,
      'status', o.status, 'cancel_reason', o.cancel_reason, 'cancelled_at', o.cancelled_at,
      'stage', o.stage, 'preparing_at', o.preparing_at, 'at_cashier_at', o.at_cashier_at, 'out_at', o.out_at,
      'customer_name', o.customer_name, 'customer_phone', o.customer_phone, 'customer_phone2', o.customer_phone2,
      'area_name', o.area_name, 'address_label', o.address_label, 'street', o.street,
      'housing_type', o.housing_type, 'address_notes', o.address_notes,
      'note', o.note, 'agent_name', coalesce(o.agent_name, o.created_by_name),
      'items', coalesce((select jsonb_agg(jsonb_build_object(
                  'name', i.product_name, 'qty', i.qty, 'weight_grams', i.weight_grams, 'note', i.note)
                  order by i.line_no)
                from public.cc_order_items i where i.order_id = o.id), '[]'::jsonb))
      from public.cc_orders o
     where o.created_at >= v_day_start
        or (o.status <> 'cancelled' and o.stage <> 'out' and o.created_at > now() - interval '3 days')
     order by o.created_at;
end;
$$;

-- ---------------------------------------------------------------------
-- Move an order one step forward (or one step back after a wrong tap).
-- ---------------------------------------------------------------------
create or replace function public.cc_set_stage(p_order_id uuid, p_stage text)
returns jsonb
language plpgsql security definer
set search_path = ''
as $$
declare
  v_order  public.cc_orders;
  v_stages text[] := array['new', 'preparing', 'at_cashier', 'out'];
  v_from   int;
  v_to     int;
  v_name   text;
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'تغيير حالة التجهيز للفرع بس' using errcode = '42501';
  end if;
  v_to := array_position(v_stages, p_stage);
  if v_to is null then
    raise exception 'حالة غير معروفة' using errcode = '22023', hint = 'stage';
  end if;

  select * into v_order from public.cc_orders where id = p_order_id for update;
  if not found then
    raise exception 'الطلب غير موجود' using errcode = 'P0002';
  end if;
  if v_order.status = 'cancelled' then
    raise exception 'الطلب ده اتلغى — متكملش تجهيزه' using errcode = '22023', hint = 'cancelled';
  end if;
  v_from := array_position(v_stages, v_order.stage);
  if v_to = v_from then
    return jsonb_build_object('id', v_order.id, 'stage', v_order.stage);   -- double tap: nothing to do
  end if;
  if abs(v_to - v_from) <> 1 then
    raise exception 'الطلب اتغيرت حالته من جهاز تاني — اعمل تحديث' using errcode = '22023', hint = 'stale';
  end if;

  select u.email::text into v_name from auth.users u where u.id = auth.uid();
  update public.cc_orders
     set stage = p_stage,
         -- forward: stamp the new stage · back: clear the stage that was undone (earlier times stay)
         preparing_at  = case when v_to > v_from and p_stage = 'preparing'  then now() when v_to < 2 then null else preparing_at end,
         at_cashier_at = case when v_to > v_from and p_stage = 'at_cashier' then now() when v_to < 3 then null else at_cashier_at end,
         out_at        = case when v_to > v_from and p_stage = 'out'        then now() when v_to < 4 then null else out_at end,
         stage_by_name = v_name
   where id = p_order_id
  returning * into v_order;
  insert into public.cc_order_stage_events (order_id, stage, by_user, by_name) values (p_order_id, p_stage, auth.uid(), v_name);
  return jsonb_build_object('id', v_order.id, 'stage', v_order.stage, 'preparing_at', v_order.preparing_at,
    'at_cashier_at', v_order.at_cashier_at, 'out_at', v_order.out_at);
end;
$$;

revoke all on function public.cc_prep_orders()          from public, anon;
revoke all on function public.cc_set_stage(uuid, text)  from public, anon;
grant execute on function public.cc_prep_orders()         to authenticated;
grant execute on function public.cc_set_stage(uuid, text) to authenticated;

-- ===== 10_edit_order.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — edit an order until it reaches the cashier (FOR REVIEW)
--
--  CONFIRMED: the call center can change an order's items, quantities, delivery
--  address and note while it is «جديد» or «بيتجهز». From «على الكاشير» on, the
--  bill is already in Foodics, so changes go by phone with the branch.
--  The preparation screen marks the order «اتعدّل» with what changed, until the
--  person preparing taps «شُفت التعديل». The call center prints the ticket again.
--
--  Prices: lines that were already in the order keep their original price; a
--  newly added product takes today's price. Totals are computed here.
--  The customer's saved address book is not changed by an edit (only this order).
--
--  CALL-CENTER ONLY. Nothing from before is lost: every edit keeps the old and
--  new items, address and totals in cc_order_edits. Additive, plus:
--    • cc_prep_orders (09) also returns the edit mark;
--    • the old direct functions cc_create_order / cc_cancel_order are no longer
--      callable from the app (it uses cc_place_order / cc_cancel_order_as, which
--      check the role); they keep working inside those two.
--  Safe to re-run.
-- =====================================================================

alter table public.cc_orders add column if not exists edited_at      timestamptz;
alter table public.cc_orders add column if not exists edit_count     integer not null default 0;
alter table public.cc_orders add column if not exists edited_by_name text;
alter table public.cc_orders add column if not exists edit_changes   jsonb;        -- what changed in the last edit
alter table public.cc_orders add column if not exists edit_seen_at   timestamptz;  -- the branch saw the last edit

create table if not exists public.cc_order_edits (
  id          bigint generated always as identity primary key,
  order_id    uuid not null references public.cc_orders(id),
  at          timestamptz not null default now(),
  by_user     uuid references auth.users(id),
  agent_name  text,
  old_items   jsonb not null,
  new_items   jsonb not null,
  old_address jsonb not null,
  new_address jsonb not null,
  old_note    text,
  new_note    text,
  old_total   numeric(12,2) not null,
  new_total   numeric(12,2) not null,
  changes     jsonb not null
);
create index if not exists cc_order_edits_order_idx on public.cc_order_edits (order_id, at);
alter table public.cc_order_edits enable row level security;
revoke all on public.cc_order_edits from anon, authenticated, public;

-- ---------------------------------------------------------------------
-- Edit an order.
--   p_address : null = keep · {"area_id", "street", "housing_type"?, "notes"?}
--   p_items   : same as when creating ([{sku, qty} | {sku, weight_grams}, note?])
--   p_note    : the order note (empty = none)
-- ---------------------------------------------------------------------
create or replace function public.cc_edit_order(p_agent_id uuid, p_order_id uuid, p_address jsonb, p_items jsonb, p_note text)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent    public.cc_agents;
  v_order    public.cc_orders;
  v_area     public.cc_delivery_areas;
  v_housing  text;
  v_street   text;
  v_notes    text;
  v_item     jsonb;
  v_prod     record;
  v_qty      int;
  v_grams    int;
  v_sold_by  text;
  v_price    numeric(12,2);
  v_total    numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_est      boolean := false;
  v_lines    jsonb := '[]'::jsonb;
  v_line_no  int := 0;
  v_old      jsonb;
  v_changes  jsonb := '[]'::jsonb;
  v_note     text := left(nullif(btrim(p_note), ''), 300);
  v_old_addr jsonb;
  v_new_addr jsonb;
  v_fee      numeric(10,2);
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  v_agent := public.cc_require_agent(p_agent_id);

  select * into v_order from public.cc_orders where id = p_order_id for update;
  if not found then
    raise exception 'الطلب غير موجود' using errcode = 'P0002';
  end if;
  if v_order.status = 'cancelled' then
    raise exception 'الطلب ده ملغي — مينفعش يتعدّل' using errcode = '22023', hint = 'status';
  end if;
  if v_order.stage not in ('new', 'preparing') then
    raise exception 'الطلب وصل الكاشير — أي تعديل يبقى بالتليفون مع الفرع' using errcode = '22023', hint = 'stage';
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 100 then
    raise exception 'السلة فارغة أو غير صحيحة' using errcode = '22023', hint = 'items';
  end if;

  -- Address on this order (the saved address book is not touched).
  v_area := null;
  select * into v_area from public.cc_delivery_areas where id = v_order.area_id;
  v_street := v_order.street; v_housing := v_order.housing_type; v_notes := v_order.address_notes;
  if p_address is not null then
    if nullif(p_address->>'area_id', '') is null then
      raise exception 'اختر منطقة التوصيل' using errcode = '22023', hint = 'areaId';
    end if;
    if char_length(coalesce(btrim(p_address->>'street'), '')) not between 1 and 150 then
      raise exception 'الشارع مطلوب وبحد أقصى 150 حرف' using errcode = '22023', hint = 'street';
    end if;
    v_housing := nullif(btrim(p_address->>'housing_type'), '');
    if v_housing is not null and v_housing not in ('building', 'villa', 'office') then
      raise exception 'نوع السكن غير صحيح' using errcode = '22023', hint = 'housingType';
    end if;
    if char_length(coalesce(p_address->>'notes', '')) > 200 then
      raise exception 'المعلومات الإضافية بحد أقصى 200 حرف' using errcode = '22023', hint = 'notes';
    end if;
    v_street := btrim(p_address->>'street');
    v_notes := nullif(btrim(p_address->>'notes'), '');
    if (p_address->>'area_id')::uuid <> v_order.area_id then
      select * into v_area from public.cc_delivery_areas where id = (p_address->>'area_id')::uuid;
      if not found or not v_area.active then
        raise exception 'منطقة التوصيل غير متاحة' using errcode = '22023', hint = 'areaId';
      end if;
    end if;
  end if;

  -- Old lines (to keep their prices and to show what changed).
  select coalesce(jsonb_agg(jsonb_build_object('sku', i.sku, 'name', i.product_name, 'unit_price', i.unit_price,
           'qty', i.qty, 'weight_grams', i.weight_grams, 'note', i.note, 'line_total', i.line_total) order by i.line_no), '[]'::jsonb)
    into v_old from public.cc_order_items i where i.order_id = p_order_id;

  -- New lines: same checks as a new order.
  for v_item in select value from jsonb_array_elements(p_items) loop
    v_line_no := v_line_no + 1;
    begin
      select p.sku, p.name, coalesce(p.price, 0)::numeric(12,2) as price into strict v_prod
        from public.products_master p where p.sku = v_item->>'sku';
    exception
      when no_data_found then
        raise exception 'صنف غير موجود: %', v_item->>'sku' using errcode = 'P0002', hint = 'items';
      when too_many_rows then
        raise exception 'كود الصنف % مكرر في شيت المنتجات — لازم يتصلح في الشيت الأول', v_item->>'sku' using errcode = 'P0003', hint = 'items';
    end;
    if v_item ? 'qty' and coalesce(v_item->>'qty', '') !~ '^[0-9]+$' then
      if v_item->>'qty' ~ '^[0-9]*[.][0-9]+$' then
        raise exception 'لا يمكن أن تحتوي الكمية على أرقام عشرية في المنتجات التي يتم بيعها بالوحدة. (السطر %)', v_line_no using errcode = '22023', hint = 'items';
      end if;
      raise exception 'الكمية غير صحيحة في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    if v_item ? 'weight_grams' and coalesce(v_item->>'weight_grams', '') !~ '^[0-9]+$' then
      raise exception 'الوزن غير صحيح في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    v_qty := (v_item->>'qty')::int;
    v_grams := (v_item->>'weight_grams')::int;
    if (v_qty is null) = (v_grams is null) then
      raise exception 'السطر % لازم يكون بالكمية أو بالوزن', v_line_no using errcode = '22023', hint = 'items';
    end if;
    v_sold_by := coalesce(public.cc_sold_by(v_prod.sku), 'unit');
    if v_sold_by = 'unit' and v_grams is not null then
      raise exception 'الصنف «%» بيتباع بالوحدة — اكتب الكمية بالعدد', v_prod.name using errcode = '22023', hint = 'items';
    end if;
    if v_sold_by = 'weight' and v_qty is not null then
      raise exception 'الصنف «%» بيتباع بالوزن — اكتب الوزن بالكيلو', v_prod.name using errcode = '22023', hint = 'items';
    end if;
    if v_qty is not null and v_qty not between 1 and 999 then
      raise exception 'الكمية غير صحيحة في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    if v_grams is not null and v_grams not between 10 and 20000 then
      raise exception 'الوزن غير صحيح في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;

    -- A product that was already in the order keeps its original price.
    select (o->>'unit_price')::numeric(12,2) into v_price
      from jsonb_array_elements(v_old) o where o->>'sku' = v_prod.sku limit 1;
    v_price := coalesce(v_price, v_prod.price);
    if v_grams is not null then
      v_total := round(v_price * v_grams / 1000.0, 2); v_est := true;
    else
      v_total := round(v_price * v_qty, 2);
    end if;
    v_subtotal := v_subtotal + v_total;
    v_lines := v_lines || jsonb_build_object('line_no', v_line_no, 'sku', v_prod.sku, 'product_name', v_prod.name,
      'unit_price', v_price, 'qty', v_qty, 'weight_grams', v_grams, 'line_total', v_total,
      'note', left(nullif(btrim(v_item->>'note'), ''), 120));
  end loop;

  -- What changed, per product (added / removed / amount / note), then address and note.
  select coalesce(jsonb_agg(c order by c->>'name'), '[]'::jsonb) into v_changes from (
    select case
             when o.sku is null then jsonb_build_object('kind', 'added', 'name', n.name, 'to', n.amount)
             when n.sku is null then jsonb_build_object('kind', 'removed', 'name', o.name, 'from', o.amount)
             when o.amount <> n.amount then jsonb_build_object('kind', 'amount', 'name', n.name, 'from', o.amount, 'to', n.amount)
             else jsonb_build_object('kind', 'note', 'name', n.name, 'to', coalesce(n.note, ''))
           end as c
      from (select x->>'sku' sku, min(x->>'name') name, jsonb_build_object('qty', sum((x->>'qty')::int), 'grams', sum((x->>'weight_grams')::int)) amount,
                   string_agg(x->>'note', ' · ') note
              from jsonb_array_elements(v_old) x group by x->>'sku') o
      full join (select x->>'sku' sku, min(x->>'product_name') name, jsonb_build_object('qty', sum((x->>'qty')::int), 'grams', sum((x->>'weight_grams')::int)) amount,
                   string_agg(x->>'note', ' · ') note
              from jsonb_array_elements(v_lines) x group by x->>'sku') n on n.sku = o.sku
     where o.sku is null or n.sku is null or o.amount <> n.amount or o.note is distinct from n.note) t;

  v_old_addr := jsonb_build_object('area', v_order.area_name, 'street', v_order.street, 'housing_type', v_order.housing_type, 'notes', v_order.address_notes);
  v_new_addr := jsonb_build_object('area', v_area.name, 'street', v_street, 'housing_type', v_housing, 'notes', v_notes);
  -- Same area → the fee the customer was told stays; another area → that area's fee today.
  v_fee := case when v_area.id = v_order.area_id then v_order.delivery_fee else v_area.fee end;
  if v_area.id = v_order.area_id then v_new_addr := v_new_addr || jsonb_build_object('area', v_order.area_name); end if;
  if v_new_addr <> v_old_addr then
    v_changes := v_changes || jsonb_build_object('kind', 'address', 'name', 'العنوان', 'from', v_old_addr, 'to', v_new_addr);
  end if;
  if v_note is distinct from v_order.note then
    v_changes := v_changes || jsonb_build_object('kind', 'order_note', 'name', 'ملاحظات الطلب', 'to', coalesce(v_note, ''));
  end if;
  if jsonb_array_length(v_changes) = 0 then
    raise exception 'مفيش أي تغيير في الطلب' using errcode = '22023', hint = 'nochange';
  end if;

  insert into public.cc_order_edits (order_id, by_user, agent_name, old_items, new_items, old_address, new_address,
                                     old_note, new_note, old_total, new_total, changes)
  values (p_order_id, auth.uid(), v_agent.name, v_old, v_lines, v_old_addr, v_new_addr,
          v_order.note, v_note, v_order.total, v_subtotal + v_fee, v_changes);

  -- Replace the lines (the old ones are kept above in cc_order_edits).
  delete from public.cc_order_items where order_id = p_order_id;
  insert into public.cc_order_items (order_id, line_no, sku, product_name, unit_price, qty, weight_grams, line_total, note)
  select p_order_id, l.line_no, l.sku, l.product_name, l.unit_price, l.qty, l.weight_grams, l.line_total, l.note
    from jsonb_to_recordset(v_lines) as l(line_no int, sku text, product_name text, unit_price numeric, qty int,
                                          weight_grams int, line_total numeric, note text);

  update public.cc_orders
     set area_id = v_area.id, area_name = case when v_area.id = v_order.area_id then v_order.area_name else v_area.name end,
         street = v_street, housing_type = v_housing, address_notes = v_notes,
         delivery_fee = v_fee, subtotal = v_subtotal, total = v_subtotal + v_fee, is_estimated = v_est,
         note = v_note, edited_at = now(), edit_count = edit_count + 1, edited_by_name = v_agent.name,
         edit_changes = v_changes, edit_seen_at = null
   where id = p_order_id
  returning * into v_order;
  return v_order;
end;
$$;

-- The branch saw the last edit (the «اتعدّل» mark goes away).
create or replace function public.cc_ack_edit(p_order_id uuid)
returns boolean
language plpgsql security definer
set search_path = ''
as $$
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'للفرع بس' using errcode = '42501';
  end if;
  update public.cc_orders set edit_seen_at = now() where id = p_order_id and edited_at is not null;
  return found;
end;
$$;

-- The preparation list also carries the edit mark (same as 09 plus edited_* fields).
create or replace function public.cc_prep_orders()
returns setof jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Africa/Cairo')) at time zone 'Africa/Cairo';
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'شاشة التجهيز للفرع بس' using errcode = '42501';
  end if;
  return query
    select jsonb_build_object(
      'id', o.id, 'order_no', o.order_no, 'created_at', o.created_at,
      'status', o.status, 'cancel_reason', o.cancel_reason, 'cancelled_at', o.cancelled_at,
      'stage', o.stage, 'preparing_at', o.preparing_at, 'at_cashier_at', o.at_cashier_at, 'out_at', o.out_at,
      'customer_name', o.customer_name, 'customer_phone', o.customer_phone, 'customer_phone2', o.customer_phone2,
      'area_name', o.area_name, 'address_label', o.address_label, 'street', o.street,
      'housing_type', o.housing_type, 'address_notes', o.address_notes,
      'note', o.note, 'agent_name', coalesce(o.agent_name, o.created_by_name),
      'edited_at', o.edited_at, 'edit_count', o.edit_count, 'edit_changes', o.edit_changes, 'edit_seen_at', o.edit_seen_at,
      'items', coalesce((select jsonb_agg(jsonb_build_object(
                  'name', i.product_name, 'qty', i.qty, 'weight_grams', i.weight_grams, 'note', i.note)
                  order by i.line_no)
                from public.cc_order_items i where i.order_id = o.id), '[]'::jsonb))
      from public.cc_orders o
     where o.created_at >= v_day_start
        or (o.status <> 'cancelled' and o.stage <> 'out' and o.created_at > now() - interval '3 days')
     order by o.created_at;
end;
$$;

revoke all on function public.cc_edit_order(uuid, uuid, jsonb, jsonb, text) from public, anon;
revoke all on function public.cc_ack_edit(uuid) from public, anon;
grant execute on function public.cc_edit_order(uuid, uuid, jsonb, jsonb, text) to authenticated;
grant execute on function public.cc_ack_edit(uuid) to authenticated;

-- Only the role-checked wrappers create and cancel orders from the app.
revoke execute on function public.cc_create_order(uuid, jsonb, jsonb, jsonb, text) from authenticated;
revoke execute on function public.cc_cancel_order(uuid, text) from authenticated;

-- ===== 11_driver.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — the driver who took the order out (FOR REVIEW)
--
--  CONFIRMED: when the branch taps «خرج مع الطيار» it types the driver in ONE
--  field — the name with the number in brackets, e.g. «محمد (01012345678)».
--  The call center sees it on the board and in the order details.
--
--  CALL-CENTER ONLY, ADDITIVE: one new column on cc_orders and one new function
--  (cc_send_out = «خرج مع الطيار» with the driver). The preparation list (09/10)
--  also returns the driver. Nothing is dropped or deleted. Safe to re-run.
-- =====================================================================

alter table public.cc_orders add column if not exists driver text;    -- «الاسم (الرقم)» as typed

-- «خرج مع الطيار» with the driver: from «على الكاشير» only (same rules as cc_set_stage).
create or replace function public.cc_send_out(p_order_id uuid, p_driver text)
returns jsonb
language plpgsql security definer
set search_path = ''
as $$
declare
  v_driver text := btrim(regexp_replace(coalesce(p_driver, ''), '\s+', ' ', 'g'));
  v_stage  text;
  v_res    jsonb;
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'تغيير حالة التجهيز للفرع بس' using errcode = '42501';
  end if;
  if char_length(v_driver) not between 2 and 80 then
    raise exception 'اكتب اسم الطيار ورقمه — مثال: محمد (01012345678)' using errcode = '22023', hint = 'driver';
  end if;
  select stage into v_stage from public.cc_orders where id = p_order_id;
  if v_stage = 'out' then
    raise exception 'الطلب خرج بالفعل' using errcode = '22023', hint = 'stale';
  end if;
  v_res := public.cc_set_stage(p_order_id, 'out');       -- checks cancelled / one step at a time, logs the tap
  update public.cc_orders set driver = v_driver where id = p_order_id;
  return v_res || jsonb_build_object('driver', v_driver);
end;
$$;
revoke all on function public.cc_send_out(uuid, text) from public, anon;
grant execute on function public.cc_send_out(uuid, text) to authenticated;

-- The preparation list also carries the driver (same as 10_edit_order.sql plus "driver").
create or replace function public.cc_prep_orders()
returns setof jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Africa/Cairo')) at time zone 'Africa/Cairo';
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'شاشة التجهيز للفرع بس' using errcode = '42501';
  end if;
  return query
    select jsonb_build_object(
      'id', o.id, 'order_no', o.order_no, 'created_at', o.created_at,
      'status', o.status, 'cancel_reason', o.cancel_reason, 'cancelled_at', o.cancelled_at,
      'stage', o.stage, 'preparing_at', o.preparing_at, 'at_cashier_at', o.at_cashier_at, 'out_at', o.out_at,
      'driver', o.driver,
      'customer_name', o.customer_name, 'customer_phone', o.customer_phone, 'customer_phone2', o.customer_phone2,
      'area_name', o.area_name, 'address_label', o.address_label, 'street', o.street,
      'housing_type', o.housing_type, 'address_notes', o.address_notes,
      'note', o.note, 'agent_name', coalesce(o.agent_name, o.created_by_name),
      'edited_at', o.edited_at, 'edit_count', o.edit_count, 'edit_changes', o.edit_changes, 'edit_seen_at', o.edit_seen_at,
      'items', coalesce((select jsonb_agg(jsonb_build_object(
                  'name', i.product_name, 'qty', i.qty, 'weight_grams', i.weight_grams, 'note', i.note)
                  order by i.line_no)
                from public.cc_order_items i where i.order_id = o.id), '[]'::jsonb))
      from public.cc_orders o
     where o.created_at >= v_day_start
        or (o.status <> 'cancelled' and o.stage <> 'out' and o.created_at > now() - interval '3 days')
     order by o.created_at;
end;
$$;

-- ===== 12_active_products.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — show only products Foodics shows (FOR REVIEW)
--
--  CONFIRMED: like Foodics, the call center lists only products that are
--    • in the current products sheet and active there (is_active not "No"), and
--    • priced above zero.
--  Inactive products, zero-price products and old rows that are no longer in the
--  products sheet are not shown (search, categories, repeat order).
--
--  CALL-CENTER ONLY: replaces the body of cc_list_products (same name, same
--  columns). The data-center table dc_products is only READ. No table is
--  changed, nothing is deleted. Safe to re-run.
-- =====================================================================

create or replace function public.cc_list_products(p_after_sku text default null, p_limit int default 1000)
returns table (sku text, name text, barcode text, price numeric, sold_by text)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;

  if to_regclass('public.dc_products') is null then
    -- Test projects without the data-center tables: price rule only.
    return query
      select p.sku, p.name, p.barcode, p.price::numeric(12,2), coalesce(public.cc_sold_by(p.sku), 'unit')
        from public.products_master p
       where p.sku is not null and coalesce(p.price, 0) > 0
         and (p_after_sku is null or p.sku > p_after_sku)
         and not exists (select 1 from public.products_master d where d.sku = p.sku and d.ctid <> p.ctid)
       order by p.sku
       limit least(greatest(coalesce(p_limit, 1000), 1), 1000);
    return;
  end if;

  return query
    select p.sku, p.name, p.barcode, p.price::numeric(12,2), coalesce(public.cc_sold_by(p.sku), 'unit')
      from public.products_master p
     where p.sku is not null and coalesce(p.price, 0) > 0
       and (p_after_sku is null or p.sku > p_after_sku)
       and not exists (select 1 from public.products_master d where d.sku = p.sku and d.ctid <> p.ctid)
       -- in the current products sheet, and not marked inactive there
       and exists (select 1 from public.dc_products s where s.sku = p.sku and s.is_active is not false)
     order by p.sku
     limit least(greatest(coalesce(p_limit, 1000), 1), 1000);
end;
$$;

revoke all on function public.cc_list_products(text, int) from public, anon;
grant execute on function public.cc_list_products(text, int) to authenticated;

-- ===== 13_modifiers.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — product add-ons, like Foodics (FOR REVIEW)
--
--  CONFIRMED: choosing a product that has add-ons (e.g. «ارز بلبن ابو الفضل»)
--  opens a list of its add-on groups with + / −, the price of each option and
--  the limit of each group (e.g. «اضافة مكسرات ايس كريم — لا تزيد عن 5»).
--  A group with a minimum must be chosen (e.g. the ice-cream flavour).
--
--    • cc_modifier_groups / cc_modifier_options : the add-ons and their prices,
--      imported from the Foodics export (الاضافات / خيارات الاضافات);
--    • cc_product_modifiers : which product shows which group, with min / max —
--      set by the admin in «الإعدادات ← الإضافات»;
--    • cc_order_items.modifiers : the add-ons of each order line (name, price,
--      quantity copied in, so a later price change never alters an order).
--
--  Prices of add-ons come from the database, never from the app. An add-on is
--  counted per piece: 2 × أرز بلبن with عسل ×1 = 2 × (product + عسل).
--  Editing an order keeps the price of an add-on that was already on the line.
--
--  CALL-CENTER ONLY. New cc_* tables, one new column on cc_order_items, and new
--  bodies for cc_place_order / cc_edit_order / cc_prep_orders (same names and
--  arguments). Needs 10_edit_order.sql and 11_driver.sql first. Nothing is
--  dropped or deleted; products_master is only read. Safe to re-run.
-- =====================================================================

create table if not exists public.cc_modifier_groups (
  id         uuid primary key,                       -- Foodics id
  name       text not null check (char_length(btrim(name)) between 1 and 80),
  active     boolean not null default true,
  updated_at timestamptz not null default now()
);

create table if not exists public.cc_modifier_options (
  id         uuid primary key,                       -- Foodics id
  group_id   uuid not null references public.cc_modifier_groups(id),
  name       text not null check (char_length(btrim(name)) between 1 and 80),
  sku        text,
  price      numeric(10,2) not null check (price >= 0),
  active     boolean not null default true,
  sort       integer not null default 0,
  updated_at timestamptz not null default now()
);
create index if not exists cc_modifier_options_group_idx on public.cc_modifier_options (group_id, sort);

create table if not exists public.cc_product_modifiers (
  sku        text not null,
  group_id   uuid not null references public.cc_modifier_groups(id),
  min_qty    integer not null default 0 check (min_qty between 0 and 20),
  max_qty    integer not null default 5 check (max_qty between 1 and 20),
  sort       integer not null default 0,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id),
  primary key (sku, group_id),
  constraint cc_product_modifiers_min_max check (min_qty <= max_qty)
);

-- [{id, group_id, group, name, price, qty}] per line; null = no add-ons.
alter table public.cc_order_items add column if not exists modifiers jsonb;

-- Read and written only through the functions below.
alter table public.cc_modifier_groups   enable row level security;
alter table public.cc_modifier_options  enable row level security;
alter table public.cc_product_modifiers enable row level security;
revoke all on public.cc_modifier_groups, public.cc_modifier_options, public.cc_product_modifiers from anon, authenticated, public;

-- ---------------------------------------------------------------------
-- Add-ons for the order screen: active groups with their options, and the
-- product links. One call, loaded with the products.
-- ---------------------------------------------------------------------
create or replace function public.cc_list_modifiers()
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'groups', coalesce((
      select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name, 'options', o.list) order by g.name)
        from public.cc_modifier_groups g
        cross join lateral (
          select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'price', x.price) order by x.sort, x.name), '[]'::jsonb) list
            from public.cc_modifier_options x where x.group_id = g.id and x.active) o
       where g.active and jsonb_array_length(o.list) > 0), '[]'::jsonb),
    'links', coalesce((
      select jsonb_agg(jsonb_build_object('sku', l.sku, 'group_id', l.group_id, 'min', l.min_qty, 'max', l.max_qty) order by l.sku, l.sort)
        from public.cc_product_modifiers l
        join public.cc_modifier_groups g on g.id = l.group_id and g.active), '[]'::jsonb));
end;
$$;

-- ---------------------------------------------------------------------
-- Admin: the add-on groups of one product (replaces its list).
--   p_links : [{"group_id": uuid, "min": int, "max": int}, ...] in display order; [] = none.
-- ---------------------------------------------------------------------
create or replace function public.cc_save_product_modifiers(p_sku text, p_links jsonb)
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  v_link jsonb;
  v_n    integer := 0;
  v_min  integer;
  v_max  integer;
begin
  if not public.cc_is_admin() then
    raise exception 'للمسؤول فقط' using errcode = '42501';
  end if;
  if not exists (select 1 from public.products_master p where p.sku = p_sku) then
    raise exception 'صنف غير موجود: %', p_sku using errcode = 'P0002', hint = 'sku';
  end if;
  if jsonb_typeof(p_links) is distinct from 'array' or jsonb_array_length(p_links) > 15 then
    raise exception 'قائمة الإضافات غير صحيحة' using errcode = '22023', hint = 'links';
  end if;

  delete from public.cc_product_modifiers where sku = p_sku;
  for v_link in select value from jsonb_array_elements(p_links) loop
    v_n := v_n + 1;
    if coalesce(v_link->>'min', '0') !~ '^[0-9]+$' or coalesce(v_link->>'max', '') !~ '^[0-9]+$' then
      raise exception 'الحد الأدنى والأقصى لازم يكونوا أرقام' using errcode = '22023', hint = 'links';
    end if;
    v_min := coalesce((v_link->>'min')::int, 0);
    v_max := (v_link->>'max')::int;
    if v_max not between 1 and 20 or v_min > v_max then
      raise exception 'الحد الأقصى من 1 إلى 20 ولا يقل عن الحد الأدنى' using errcode = '22023', hint = 'links';
    end if;
    if not exists (select 1 from public.cc_modifier_groups g where g.id::text = v_link->>'group_id' and g.active) then
      raise exception 'مجموعة إضافات غير موجودة' using errcode = 'P0002', hint = 'links';
    end if;
    begin
      insert into public.cc_product_modifiers (sku, group_id, min_qty, max_qty, sort, updated_by)
      values (p_sku, (v_link->>'group_id')::uuid, v_min, v_max, v_n, auth.uid());
    exception when unique_violation then
      raise exception 'المجموعة مكررة لنفس الصنف' using errcode = '23505', hint = 'links';
    end;
  end loop;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------
-- Price and check the add-ons of one order line (used by cc_place_order and
-- cc_edit_order; not callable from the app).
--   p_mods : [{"id": option uuid, "qty": int}, ...] or null
--   p_mult : pieces on the line (1 for a line sold by weight)
--   p_old  : add-ons already on this product in the order (their price is kept)
-- Returns {"items": [...snapshot...], "total": add-ons × pieces}.
-- ---------------------------------------------------------------------
create or replace function public.cc_price_modifiers(p_sku text, p_mods jsonb, p_mult integer, p_old jsonb default null)
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_m     jsonb;
  v_opt   record;
  v_link  record;
  v_qty   integer;
  v_price numeric(10,2);
  v_sum   integer;
  v_items jsonb := '[]'::jsonb;
  v_total numeric(12,2) := 0;
  v_pname text;
begin
  if p_mods is null or jsonb_typeof(p_mods) = 'null' then
    p_mods := '[]'::jsonb;
  end if;
  if jsonb_typeof(p_mods) <> 'array' or jsonb_array_length(p_mods) > 40 then
    raise exception 'الإضافات غير صحيحة' using errcode = '22023', hint = 'items';
  end if;
  select min(p.name) into v_pname from public.products_master p where p.sku = p_sku;

  for v_m in select value from jsonb_array_elements(p_mods) loop
    if coalesce(v_m->>'qty', '') !~ '^[0-9]+$' or (v_m->>'qty')::int not between 1 and 20 then
      raise exception 'عدد الإضافة غير صحيح في «%»', v_pname using errcode = '22023', hint = 'items';
    end if;
    v_qty := (v_m->>'qty')::int;
    select o.id, o.name, o.price, g.id as group_id, g.name as group_name into v_opt
      from public.cc_modifier_options o
      join public.cc_modifier_groups g on g.id = o.group_id
     where o.id::text = v_m->>'id' and o.active and g.active
       and exists (select 1 from public.cc_product_modifiers l where l.sku = p_sku and l.group_id = g.id);
    if not found then
      raise exception 'إضافة غير متاحة لـ«%» — حدّث الصفحة واختر مرة أخرى', v_pname using errcode = 'P0002', hint = 'items';
    end if;
    if exists (select 1 from jsonb_array_elements(v_items) x where x->>'id' = v_opt.id::text) then
      raise exception 'الإضافة «%» مكررة في «%»', v_opt.name, v_pname using errcode = '22023', hint = 'items';
    end if;
    select (x->>'price')::numeric(10,2) into v_price
      from jsonb_array_elements(case when jsonb_typeof(p_old) = 'array' then p_old else '[]'::jsonb end) x
     where x->>'id' = v_opt.id::text limit 1;
    v_price := coalesce(v_price, v_opt.price);
    v_items := v_items || jsonb_build_object('id', v_opt.id, 'group_id', v_opt.group_id, 'group', v_opt.group_name,
                                             'name', v_opt.name, 'price', v_price, 'qty', v_qty);
    v_total := v_total + v_price * v_qty;
  end loop;

  -- Limits of every group linked to the product.
  for v_link in
    select l.group_id, l.min_qty, l.max_qty, g.name
      from public.cc_product_modifiers l join public.cc_modifier_groups g on g.id = l.group_id and g.active
     where l.sku = p_sku
  loop
    select coalesce(sum((x->>'qty')::int), 0) into v_sum
      from jsonb_array_elements(v_items) x where x->>'group_id' = v_link.group_id::text;
    if v_sum < v_link.min_qty then
      raise exception 'اختر % على الأقل من «%» في «%»', v_link.min_qty, v_link.name, v_pname using errcode = '22023', hint = 'items';
    end if;
    if v_sum > v_link.max_qty then
      raise exception '«%» لا تزيد عن % في «%»', v_link.name, v_link.max_qty, v_pname using errcode = '22023', hint = 'items';
    end if;
  end loop;

  return jsonb_build_object('items', v_items, 'total', round(v_total * greatest(coalesce(p_mult, 1), 1), 2));
end;
$$;

-- ---------------------------------------------------------------------
-- Create an order as an employee (same as 04_agents.sql) + the add-ons of
-- each line: p_items[i].modifiers = [{"id", "qty"}]. cc_create_order ignores
-- that key; the add-ons are priced here, added to the line and order totals,
-- in the same transaction. Sending the same draft again changes nothing.
-- ---------------------------------------------------------------------
create or replace function public.cc_place_order(
  p_agent_id          uuid,
  p_client_request_id uuid,
  p_customer          jsonb,
  p_address           jsonb,
  p_items             jsonb,
  p_note              text default null
)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent public.cc_agents;
  v_order public.cc_orders;
  v_row   record;
  v_line  public.cc_order_items;
  v_mods  jsonb;
  v_add   numeric(12,2) := 0;
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  v_agent := public.cc_require_agent(p_agent_id);
  v_order := public.cc_create_order(p_client_request_id, p_customer, p_address, p_items, p_note);
  if v_order.agent_id is null then
    -- A new order (a repeated draft already has its employee and add-ons).
    for v_row in select value as item, ordinality as n from jsonb_array_elements(p_items) with ordinality loop
      select * into v_line from public.cc_order_items where order_id = v_order.id and line_no = v_row.n;
      v_mods := public.cc_price_modifiers(v_line.sku, v_row.item->'modifiers', coalesce(v_line.qty, 1), null);
      if jsonb_array_length(v_mods->'items') > 0 then
        update public.cc_order_items
           set modifiers = v_mods->'items', line_total = line_total + (v_mods->>'total')::numeric
         where id = v_line.id;
        v_add := v_add + (v_mods->>'total')::numeric;
      end if;
    end loop;
    update public.cc_orders
       set agent_id = v_agent.id, agent_name = v_agent.name,
           subtotal = subtotal + v_add, total = total + v_add
     where id = v_order.id
    returning * into v_order;
    update public.cc_order_events set by_name = v_agent.name
     where order_id = v_order.id and status = 'new';
  end if;
  return v_order;
end;
$$;

-- ---------------------------------------------------------------------
-- Edit an order: same as 10_edit_order.sql, plus each line's add-ons.
-- A change in add-ons only shows on the preparation screen as «الإضافات».
-- ---------------------------------------------------------------------
create or replace function public.cc_edit_order(p_agent_id uuid, p_order_id uuid, p_address jsonb, p_items jsonb, p_note text)
returns public.cc_orders
language plpgsql security definer
set search_path = ''
as $$
declare
  v_agent    public.cc_agents;
  v_order    public.cc_orders;
  v_area     public.cc_delivery_areas;
  v_housing  text;
  v_street   text;
  v_notes    text;
  v_item     jsonb;
  v_prod     record;
  v_qty      int;
  v_grams    int;
  v_sold_by  text;
  v_price    numeric(12,2);
  v_total    numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_est      boolean := false;
  v_lines    jsonb := '[]'::jsonb;
  v_line_no  int := 0;
  v_old      jsonb;
  v_changes  jsonb := '[]'::jsonb;
  v_note     text := left(nullif(btrim(p_note), ''), 300);
  v_old_addr jsonb;
  v_new_addr jsonb;
  v_fee      numeric(10,2);
  v_old_mods jsonb;
  v_mods     jsonb;
begin
  if not public.cc_is_staff() then
    raise exception 'غير مصرح' using errcode = '42501';
  end if;
  v_agent := public.cc_require_agent(p_agent_id);

  select * into v_order from public.cc_orders where id = p_order_id for update;
  if not found then
    raise exception 'الطلب غير موجود' using errcode = 'P0002';
  end if;
  if v_order.status = 'cancelled' then
    raise exception 'الطلب ده ملغي — مينفعش يتعدّل' using errcode = '22023', hint = 'status';
  end if;
  if v_order.stage not in ('new', 'preparing') then
    raise exception 'الطلب وصل الكاشير — أي تعديل يبقى بالتليفون مع الفرع' using errcode = '22023', hint = 'stage';
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 100 then
    raise exception 'السلة فارغة أو غير صحيحة' using errcode = '22023', hint = 'items';
  end if;

  -- Address on this order (the saved address book is not touched).
  v_area := null;
  select * into v_area from public.cc_delivery_areas where id = v_order.area_id;
  v_street := v_order.street; v_housing := v_order.housing_type; v_notes := v_order.address_notes;
  if p_address is not null then
    if nullif(p_address->>'area_id', '') is null then
      raise exception 'اختر منطقة التوصيل' using errcode = '22023', hint = 'areaId';
    end if;
    if char_length(coalesce(btrim(p_address->>'street'), '')) not between 1 and 150 then
      raise exception 'الشارع مطلوب وبحد أقصى 150 حرف' using errcode = '22023', hint = 'street';
    end if;
    v_housing := nullif(btrim(p_address->>'housing_type'), '');
    if v_housing is not null and v_housing not in ('building', 'villa', 'office') then
      raise exception 'نوع السكن غير صحيح' using errcode = '22023', hint = 'housingType';
    end if;
    if char_length(coalesce(p_address->>'notes', '')) > 200 then
      raise exception 'المعلومات الإضافية بحد أقصى 200 حرف' using errcode = '22023', hint = 'notes';
    end if;
    v_street := btrim(p_address->>'street');
    v_notes := nullif(btrim(p_address->>'notes'), '');
    if (p_address->>'area_id')::uuid <> v_order.area_id then
      select * into v_area from public.cc_delivery_areas where id = (p_address->>'area_id')::uuid;
      if not found or not v_area.active then
        raise exception 'منطقة التوصيل غير متاحة' using errcode = '22023', hint = 'areaId';
      end if;
    end if;
  end if;

  -- Old lines (to keep their prices and to show what changed).
  select coalesce(jsonb_agg(jsonb_build_object('sku', i.sku, 'name', i.product_name, 'unit_price', i.unit_price,
           'qty', i.qty, 'weight_grams', i.weight_grams, 'note', i.note, 'line_total', i.line_total,
           'modifiers', i.modifiers) order by i.line_no), '[]'::jsonb)
    into v_old from public.cc_order_items i where i.order_id = p_order_id;

  -- New lines: same checks as a new order.
  for v_item in select value from jsonb_array_elements(p_items) loop
    v_line_no := v_line_no + 1;
    begin
      select p.sku, p.name, coalesce(p.price, 0)::numeric(12,2) as price into strict v_prod
        from public.products_master p where p.sku = v_item->>'sku';
    exception
      when no_data_found then
        raise exception 'صنف غير موجود: %', v_item->>'sku' using errcode = 'P0002', hint = 'items';
      when too_many_rows then
        raise exception 'كود الصنف % مكرر في شيت المنتجات — لازم يتصلح في الشيت الأول', v_item->>'sku' using errcode = 'P0003', hint = 'items';
    end;
    if v_item ? 'qty' and coalesce(v_item->>'qty', '') !~ '^[0-9]+$' then
      if v_item->>'qty' ~ '^[0-9]*[.][0-9]+$' then
        raise exception 'لا يمكن أن تحتوي الكمية على أرقام عشرية في المنتجات التي يتم بيعها بالوحدة. (السطر %)', v_line_no using errcode = '22023', hint = 'items';
      end if;
      raise exception 'الكمية غير صحيحة في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    if v_item ? 'weight_grams' and coalesce(v_item->>'weight_grams', '') !~ '^[0-9]+$' then
      raise exception 'الوزن غير صحيح في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    v_qty := (v_item->>'qty')::int;
    v_grams := (v_item->>'weight_grams')::int;
    if (v_qty is null) = (v_grams is null) then
      raise exception 'السطر % لازم يكون بالكمية أو بالوزن', v_line_no using errcode = '22023', hint = 'items';
    end if;
    v_sold_by := coalesce(public.cc_sold_by(v_prod.sku), 'unit');
    if v_sold_by = 'unit' and v_grams is not null then
      raise exception 'الصنف «%» بيتباع بالوحدة — اكتب الكمية بالعدد', v_prod.name using errcode = '22023', hint = 'items';
    end if;
    if v_sold_by = 'weight' and v_qty is not null then
      raise exception 'الصنف «%» بيتباع بالوزن — اكتب الوزن بالكيلو', v_prod.name using errcode = '22023', hint = 'items';
    end if;
    if v_qty is not null and v_qty not between 1 and 999 then
      raise exception 'الكمية غير صحيحة في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;
    if v_grams is not null and v_grams not between 10 and 20000 then
      raise exception 'الوزن غير صحيح في السطر %', v_line_no using errcode = '22023', hint = 'items';
    end if;

    -- A product that was already in the order keeps its original price.
    select (o->>'unit_price')::numeric(12,2) into v_price
      from jsonb_array_elements(v_old) o where o->>'sku' = v_prod.sku limit 1;
    v_price := coalesce(v_price, v_prod.price);
    if v_grams is not null then
      v_total := round(v_price * v_grams / 1000.0, 2); v_est := true;
    else
      v_total := round(v_price * v_qty, 2);
    end if;
    -- Add-ons: an add-on that was already on this product keeps its original price.
    select jsonb_agg(m) into v_old_mods
      from jsonb_array_elements(v_old) o,
           jsonb_array_elements(case when jsonb_typeof(o->'modifiers') = 'array' then o->'modifiers' else '[]'::jsonb end) m
     where o->>'sku' = v_prod.sku;
    v_mods := public.cc_price_modifiers(v_prod.sku, v_item->'modifiers', coalesce(v_qty, 1), v_old_mods);
    v_total := v_total + (v_mods->>'total')::numeric;
    v_subtotal := v_subtotal + v_total;
    v_lines := v_lines || jsonb_build_object('line_no', v_line_no, 'sku', v_prod.sku, 'product_name', v_prod.name,
      'unit_price', v_price, 'qty', v_qty, 'weight_grams', v_grams, 'line_total', v_total,
      'note', left(nullif(btrim(v_item->>'note'), ''), 120),
      'modifiers', case when jsonb_array_length(v_mods->'items') > 0 then v_mods->'items' end);
  end loop;

  -- What changed, per product (added / removed / amount / note), then address and note.
  select coalesce(jsonb_agg(c order by c->>'name'), '[]'::jsonb) into v_changes from (
    select case
             when o.sku is null then jsonb_build_object('kind', 'added', 'name', n.name, 'to', n.amount)
             when n.sku is null then jsonb_build_object('kind', 'removed', 'name', o.name, 'from', o.amount)
             when o.amount <> n.amount then jsonb_build_object('kind', 'amount', 'name', n.name, 'from', o.amount, 'to', n.amount)
             when o.mods <> n.mods then jsonb_build_object('kind', 'modifiers', 'name', n.name, 'from', o.mods, 'to', n.mods)
             else jsonb_build_object('kind', 'note', 'name', n.name, 'to', coalesce(n.note, ''))
           end as c
      from (select x->>'sku' sku, min(x->>'name') name, jsonb_build_object('qty', sum((x->>'qty')::int), 'grams', sum((x->>'weight_grams')::int)) amount,
                   string_agg(x->>'note', ' · ') note,
                   coalesce(string_agg((select string_agg((m->>'name') || ' ×' || (m->>'qty'), '، ')
                     from jsonb_array_elements(case when jsonb_typeof(x->'modifiers') = 'array' then x->'modifiers' else '[]'::jsonb end) m), ' · '), '') mods
              from jsonb_array_elements(v_old) x group by x->>'sku') o
      full join (select x->>'sku' sku, min(x->>'product_name') name, jsonb_build_object('qty', sum((x->>'qty')::int), 'grams', sum((x->>'weight_grams')::int)) amount,
                   string_agg(x->>'note', ' · ') note,
                   coalesce(string_agg((select string_agg((m->>'name') || ' ×' || (m->>'qty'), '، ')
                     from jsonb_array_elements(case when jsonb_typeof(x->'modifiers') = 'array' then x->'modifiers' else '[]'::jsonb end) m), ' · '), '') mods
              from jsonb_array_elements(v_lines) x group by x->>'sku') n on n.sku = o.sku
     where o.sku is null or n.sku is null or o.amount <> n.amount or o.mods <> n.mods or o.note is distinct from n.note) t;

  v_old_addr := jsonb_build_object('area', v_order.area_name, 'street', v_order.street, 'housing_type', v_order.housing_type, 'notes', v_order.address_notes);
  v_new_addr := jsonb_build_object('area', v_area.name, 'street', v_street, 'housing_type', v_housing, 'notes', v_notes);
  -- Same area → the fee the customer was told stays; another area → that area's fee today.
  v_fee := case when v_area.id = v_order.area_id then v_order.delivery_fee else v_area.fee end;
  if v_area.id = v_order.area_id then v_new_addr := v_new_addr || jsonb_build_object('area', v_order.area_name); end if;
  if v_new_addr <> v_old_addr then
    v_changes := v_changes || jsonb_build_object('kind', 'address', 'name', 'العنوان', 'from', v_old_addr, 'to', v_new_addr);
  end if;
  if v_note is distinct from v_order.note then
    v_changes := v_changes || jsonb_build_object('kind', 'order_note', 'name', 'ملاحظات الطلب', 'to', coalesce(v_note, ''));
  end if;
  if jsonb_array_length(v_changes) = 0 then
    raise exception 'مفيش أي تغيير في الطلب' using errcode = '22023', hint = 'nochange';
  end if;

  insert into public.cc_order_edits (order_id, by_user, agent_name, old_items, new_items, old_address, new_address,
                                     old_note, new_note, old_total, new_total, changes)
  values (p_order_id, auth.uid(), v_agent.name, v_old, v_lines, v_old_addr, v_new_addr,
          v_order.note, v_note, v_order.total, v_subtotal + v_fee, v_changes);

  -- Replace the lines (the old ones are kept above in cc_order_edits).
  delete from public.cc_order_items where order_id = p_order_id;
  insert into public.cc_order_items (order_id, line_no, sku, product_name, unit_price, qty, weight_grams, line_total, note, modifiers)
  select p_order_id, l.line_no, l.sku, l.product_name, l.unit_price, l.qty, l.weight_grams, l.line_total, l.note, l.modifiers
    from jsonb_to_recordset(v_lines) as l(line_no int, sku text, product_name text, unit_price numeric, qty int,
                                          weight_grams int, line_total numeric, note text, modifiers jsonb);

  update public.cc_orders
     set area_id = v_area.id, area_name = case when v_area.id = v_order.area_id then v_order.area_name else v_area.name end,
         street = v_street, housing_type = v_housing, address_notes = v_notes,
         delivery_fee = v_fee, subtotal = v_subtotal, total = v_subtotal + v_fee, is_estimated = v_est,
         note = v_note, edited_at = now(), edit_count = edit_count + 1, edited_by_name = v_agent.name,
         edit_changes = v_changes, edit_seen_at = null
   where id = p_order_id
  returning * into v_order;
  return v_order;
end;
$$;

-- The preparation list also carries each line's add-ons (same as 11 plus modifiers).
create or replace function public.cc_prep_orders()
returns setof jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Africa/Cairo')) at time zone 'Africa/Cairo';
begin
  if coalesce(public.cc_my_role(), '') not in ('prep', 'admin') then
    raise exception 'شاشة التجهيز للفرع بس' using errcode = '42501';
  end if;
  return query
    select jsonb_build_object(
      'id', o.id, 'order_no', o.order_no, 'created_at', o.created_at,
      'status', o.status, 'cancel_reason', o.cancel_reason, 'cancelled_at', o.cancelled_at,
      'stage', o.stage, 'preparing_at', o.preparing_at, 'at_cashier_at', o.at_cashier_at, 'out_at', o.out_at,
      'driver', o.driver,
      'customer_name', o.customer_name, 'customer_phone', o.customer_phone, 'customer_phone2', o.customer_phone2,
      'area_name', o.area_name, 'address_label', o.address_label, 'street', o.street,
      'housing_type', o.housing_type, 'address_notes', o.address_notes,
      'note', o.note, 'agent_name', coalesce(o.agent_name, o.created_by_name),
      'edited_at', o.edited_at, 'edit_count', o.edit_count, 'edit_changes', o.edit_changes, 'edit_seen_at', o.edit_seen_at,
      'items', coalesce((select jsonb_agg(jsonb_build_object(
                  'name', i.product_name, 'qty', i.qty, 'weight_grams', i.weight_grams, 'note', i.note,
                  'modifiers', i.modifiers)
                  order by i.line_no)
                from public.cc_order_items i where i.order_id = o.id), '[]'::jsonb))
      from public.cc_orders o
     where o.created_at >= v_day_start
        or (o.status <> 'cancelled' and o.stage <> 'out' and o.created_at > now() - interval '3 days')
     order by o.created_at;
end;
$$;

revoke all on function public.cc_list_modifiers()                              from public, anon;
revoke all on function public.cc_save_product_modifiers(text, jsonb)           from public, anon;
revoke all on function public.cc_price_modifiers(text, jsonb, integer, jsonb) from public, anon, authenticated;
grant execute on function public.cc_list_modifiers()                    to authenticated;
grant execute on function public.cc_save_product_modifiers(text, jsonb) to authenticated;

commit;
